  const t0 = navFreeCell(Math.floor(tx / NAV_CELL), Math.floor(ty / NAV_CELL));
  if (s0 < 0 || t0 < 0) return null;
  const n = _navW * _navH, prev = new Int32Array(n).fill(-1), seen = new Uint8Array(n);
  const q = new Int32Array(n); let qh = 0, qt = 0;
