// ═══════════ TỐI GIẢN TASKBAR: 3 Ô CỐ ĐỊNH KIỂU MU ONLINE ═══════════
// Mỗi phái chỉ còn đúng 3 chiêu chủ động — 1 chiêu chính (skillA), 1 chiêu phụ (Trấn Phái), 1 buff có
// thời gian riêng từng phái — thay vì 5 ô người chơi tự gán. Toàn bộ chiêu Sổ Kỹ Năng còn lại (Cyclone,
// Nova, Flame Storm...) + hệ Tấn Chức phụ (Ám Khí/Đạn Chỉ/Linh Tiễn/Tiêu Hồn) không mất giá trị — dồn
// thành % Công Kích vĩnh viễn, tự động theo cấp/điều kiện đã có, không cần bấm nút nữa (xem calcDerived()
// và LEGACY_SECT_SKILLS bên dưới).
const BUFF_SKILL_ID = { thieulam:'gangkhi', toanchan:'elf_greaterdmg', baidasan:'dw_shield', minhgiao:'mg_battlefury', bug:'dl_commandaura' };
// Ô thứ 4 — TUYỆT CHIÊU. Taskbar cũ chỉ có 3 ô (chính/phụ/buff), nên những chiêu mang tính đặc
// trưng nhất của từng lớp trong MU — Evil Spirit, Power Slash — chỉ hiện ở mục Di Sản trong bảng K
// dưới dạng +%ST vĩnh viễn, không bao giờ được BẤM. Ô thứ 4 trả chúng về đúng chỗ.
// Hai lớp có chiêu người chơi hay gọi tên nhất đã nằm sẵn ở ô 1/ô 2 (Dark Knight: Twisting Slash;
// Dark Lord: Fire Scream), nên tuyệt chiêu của hai lớp đó lấy chiêu tiêu biểu còn lại, để mọi lớp
// đều có đúng bốn nút chứ không lớp ba lớp bốn.
const SIGNATURE_SKILL = {
  thieulam: 'dk_ragefulblow',    // Rageful Blow — bổ vũ khí xuống đất, chấn động cả vùng
  toanchan: 'elf_penetration',   // Penetration — mũi tên xuyên cả hàng
  baidasan: 'dw_evilspirit',     // Evil Spirit — u linh vây quanh
  minhgiao: 'mg_powerslash',     // Power Slash — sóng ánh sáng từ nhát chém
  bug:      'dl_chaoticdiseier', // Earthquake — giậm đất, nền nứt thành vòng (id cũ, xem VOHOC_DEFS)
};
function defaultSkillBar(sect){ return ['a', 'tp', BUFF_SKILL_ID[sect] || null, SIGNATURE_SKILL[sect] || null]; }
// Di Sản: mỗi tầng quy đổi thành % Công Kích vĩnh viễn — điều kiện mở giữ nguyên (tự ngộ theo
// cấp cho chiêu riêng của lớp qua vhLearned(), hoặc điều kiện Tấn Chức riêng cho 4 kỹ năng chung).
const LEGACY_TIER_PCT = { so:1.5, trung:2, cao:2.5, than:3.5 };
// Năm chiêu trong SIGNATURE_SKILL đã rời khỏi đây: chúng nay là chiêu BẤM ĐƯỢC ở ô 4, không còn
// quy đổi thành %ST vĩnh viễn nữa. Để cả hai chỗ thì một chiêu vừa cộng %ST vừa tung ra được.
// Mỗi lớp ĐÚNG bốn chiêu di sản, cùng bậc sơ/trung/trung/cao = +8,0% Công Kích. Bản cũ chia
// không đều: Dark Knight được 4,0% còn Dark Wizard 9,5% — cùng một hệ thống mà chênh nhau 5,5%
// Công Kích vĩnh viễn chỉ vì lớp này tình cờ khai nhiều chiêu hơn lớp kia.
const LEGACY_SECT_SKILLS = [
  'dk_cyclone','dk_lunge','dk_impale','dk_fallingslash',
  'elf_poisonarrow','elf_greaterdef','elf_holybolt','elf_fiveshot',
  'dw_lightning','dw_ice','dw_twister','dw_inferno',
  'mg_fireball','mg_powerwave','mg_twistingslash','mg_giganticstorm',
  'dl_force','dl_electricspark','dl_fireburst','dl_darkhorse'];
// Bị động CÓ TÁC DỤNG THẬT (xem calcDerived / regen / hurtMob) — không quy đổi thành %ST, vì
// bản cũ ghi "+15% HP, +10% giảm sát thương" mà không nối vào đâu cả: người chơi đọc xong tưởng
// mình có, thực tế chỉ được +2,5% Công Kích.
const CLASS_PASSIVES = ['dk_fortitude','tienthiencong','elf_heal','songthu','mg_ironwill','dl_darkraven'];
const LEGACY_UNIVERSAL_PCT = { amkhi:1.5, danchi:2, bow:2, tieuhon:3 };
// Đăng ký kỹ năng chủ động vào SKILL_DEFS — dùng chung cho castSkill(); chỉ chiêu buff (BUFF_SKILL_ID)
// thực sự nằm ở taskbar 3 ô, còn lại chỉ tồn tại để tính legacyAtkPct và hiển thị ở mục Di Sản
for (const _vid in VOHOC_DEFS){
  const _v = VOHOC_DEFS[_vid];
  if (_v.type === 'passive') continue;
  SKILL_DEFS[_vid] = { unlock:_v.unlock, kind:'vh', desc:_v.desc,
    // icon đọc động (getter) thay vì chụp giá trị một lần: cho phép probeSkillIcons() thay bằng icon
    // tự sinh khi file art khai báo chưa tồn tại — xem genSkillIcon() ngay dưới SECT_ART.
    get icon(){ return _v.icon; },
    req:()=>vhLearned(_vid),
    // Lưu ý: chuỗi này tính NGAY lúc nạp module (player chưa tồn tại) nên không được đọc player ở đây.
    reqTxt:`Tự ngộ khi đạt cấp ${_v.unlock} nếu đúng Lớp — khác Lớp cần ${VH_TIER[_v.tier].cost} 📜 Sách Kỹ Năng (bấm K để xem)` };
}
// MU không có khái niệm "dung hợp liên phái" — hệ Dung Hợp (30 chiêu) đã bị cắt hẳn theo hướng tối
// giản. Giữ FUSION_DEFS rỗng (thay vì xoá luôn định danh) để mọi chỗ tham chiếu cũ (vòng lặp/lookup)
// vẫn chạy an toàn — chỉ đơn giản là không còn chiêu dung hợp nào để tìm thấy nữa.
const FUSION_DEFS = {};

// ═══════════ CẤP KỸ NĂNG 1-120 — +2,5% ST & −0,25% hồi chiêu mỗi cấp · mốc theo cấp · ⚡tiến hóa 40/80/120 ═══════════
function skLv(id){ return (player && player.skillLv && player.skillLv[id]) || 1; }
function skLvMult(id){ return 1 + (skLv(id) - 1) * 0.025; }
function skUpCost(id){ return Math.round(150 * Math.pow(skLv(id), 1.45)); }
// Instinct (player.khi) — nơi tiêu DUY NHẤT của chỉ số này. Trước đây nó tích lũy từ đánh quái/thiền/
// nhiệm vụ rồi hiện thường trực trên HUD mà không tiêu được ở đâu cả (nơi tiêu cũ là tự tay xung Kinh
// Mạch, đã bị thay bằng tự động theo cấp) — một con số vô nghĩa cứ tăng mãi. Đường cong thoải hơn Lumen
// (mũ 1.1 so với 1.45) để nó là "tài nguyên farm tự nhiên có sẵn", không phải bức tường chặn.
function skUpKhi(id){ return Math.round(30 * Math.pow(skLv(id), 1.1) * skMileMult(id)); }
// ═══ GỘP TIỀN TỆ — bậc 4: Tâm Đắc nhập vào Instinct ═════════════════════════════════
// Tâm Đắc có ĐÚNG một nguồn (hạ tinh anh/boss) và ĐÚNG một chỗ tiêu (sáu cấp mốc của chiêu) —
// cùng hình dạng với Công Huân Lệnh đã gộp ở bậc 1. Nó lại nằm chung một nút bấm với Lumen và
// Instinct, nên người chơi phải nhìn ba ô đếm để hiểu vì sao nút xám.
// Nay cấp mốc chỉ đắt hơn bằng chính Instinct: mốc thứ n tốn (n+1) lần phí thường — đúng bậc
// thang 1💠…6💠 cũ, nhưng bằng thứ đã có sẵn trên HUD.
// Sức ép "phải đi săn tinh anh/boss" mà Tâm Đắc tạo ra không mất theo: xem rw.khi ở
// computeKillRewards — Instinct nay rơi theo loại quái thay vì 10 đều cho mọi con.
function skMileMult(id){
  const i = SK_MILESTONES.findIndex(x => x.lv === skLv(id) + 1);
  return i >= 0 ? i + 2 : 1;
}

// Mốc thuần thục của chiêu, 20-120 (nhân dồn với +2.5% ST/cấp)
const SK_MILESTONES = [
  { lv:20,  name:'Thành Thạo', dmg:0.08 },
  { lv:40,  name:'Tinh Thông', cd:0.10 },
  { lv:60,  name:'Điêu Luyện',  dmg:0.12 },
  { lv:80,  name:'Lão Luyện',   qi:0.12 },
  { lv:100, name:'Bậc Thầy',    dmg:0.15 },
  { lv:120, name:'Đại Sư',      dmg:0.20 },
];
function skMile(id){
  const lv = skLv(id); let dmg = 1, cd = 1, qi = 1;
  for (const m of SK_MILESTONES){
    if (lv >= m.lv){ if (m.dmg) dmg *= 1 + m.dmg; if (m.cd) cd *= 1 - m.cd; if (m.qi) qi *= 1 - m.qi; }
  }
  return { dmg, cd, qi };
}
// GDD Tiến Hóa Chiêu Thức: mỗi cấp −0,25% hồi chiêu (tối đa −30% ở Lv120) — cuối game tung chiêu liên tục, không khoảng chết
function skCdScale(id){ return Math.max(0.7, 1 - (skLv(id) - 1) * 0.0025); }
function effCd(id, base){ return Math.max(0.5, (base || 0) * (player.vhCdMult || 1) * skMile(id).cd * skEvoMult(id).cd * skCdScale(id)); }
// Tiến hóa chiêu ở mốc Lv 40/80/120 (bậc 0-3): kiếm/đạo/sóng/vòng nổ tăng theo bậc — vd Lục Mạch 1→2→3→4 kiếm
function evoStage(id){ const lv = skLv(id); return lv >= 120 ? 3 : lv >= 80 ? 2 : lv >= 40 ? 1 : 0; }
// ═══ Tiến Hóa Chiêu Thức — chọn nhánh (Skill Evolution Choice Nodes) ═══
// Ở mỗi mốc 40/80/120, ngoài phần tự động (thêm kiếm/sóng — evoStage ở trên, không đổi),
// người chơi chọn 1 trong 2 nhánh cho bậc đó: Bá Đạo (dồn sát thương) hoặc Tốc Chiến (dồn tốc/tiết kiệm).
// Lựa chọn lưu vĩnh viễn theo từng chiêu, độc lập giữa các chiêu — đa dạng build không tốn art mới.
const EVO_LVS = [40, 80, 120];
// Hai nhánh đầu chỉ đổi CON SỐ: chọn +14% sát thương hay −9% hồi chiêu thì cách chơi vẫn y hệt.
// Từ cấp 10 tới 120 người chơi không đổi cách bấm một lần nào. Nhánh thứ ba đổi HÀNH VI: cùng
// một chiêu, hoặc dồn vào một mục tiêu, hoặc quét cả bầy — đó mới là thứ tạo ra build.
const EVO_PATHS = {
  power: { name:'Bá Đạo',   desc:'+14% sát thương của chiêu này (dồn theo bậc)', dmg:0.14 },
  swift: { name:'Tốc Chiến', desc:'−9% hồi chiêu & −6% tiêu hao Mana của chiêu này (dồn theo bậc)', cd:0.09, qi:0.06 },
  spread:{ name:'Lan Toả',  desc:'+45% bán kính, −22% sát thương — đổi chiêu từ dồn một mục tiêu sang quét cả bầy', r:0.45, dmg:-0.22 },
};
// Tên chiêu để HIỂN THỊ. skillInfo() trả null cho id không nằm trong SKILL_DEFS (VOHOC_DEFS có
// 26 chiêu, SKILL_DEFS không phủ hết), mà mấy chỗ gọi lại đọc thẳng .name — ném lỗi và treo luôn
// luồng nâng cấp chiêu. Bài kiểm Tiến Hóa bắt được đúng ca này.
function skName(id){
  const i = skillInfo(id);
  return (i && i.name) || (VOHOC_DEFS[id] && VOHOC_DEFS[id].name)
      || (FUSION_DEFS && FUSION_DEFS[id] && FUSION_DEFS[id].name) || id;
}
function skEvoMult(id){
  const arr = (player && player.skillEvo && player.skillEvo[id]) || [];
  let dmg = 1, cd = 1, qi = 1, r = 1;
  for (const k of arr){
    const p = EVO_PATHS[k]; if (!p) continue;
    if (p.dmg) dmg *= 1 + p.dmg; if (p.cd) cd *= 1 - p.cd;
    if (p.qi) qi *= 1 - p.qi;   if (p.r)  r  *= 1 + p.r;
  }
  return { dmg, cd, qi, r };
}
function showEvoChoice(id, stageIdx){
  const stName = ['Tinh Thông · cấp 40', 'Lão Luyện · cấp 80', 'Đại Sư · cấp 120'][stageIdx] || '';
  document.getElementById('overlay-inner').innerHTML = `
    <h2 style="letter-spacing:2px">⚡ Tiến Hóa Chiêu Thức</h2>
    <p style="margin-bottom:10px"><b style="color:#ffd76a">${skName(id)}</b> đạt mốc <b>${stName}</b> —
    chọn một nhánh tiến hóa (vĩnh viễn cho bậc này, không ảnh hưởng các chiêu khác):</p>
    <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap">
      ${Object.entries(EVO_PATHS).map(([k, p]) => `
        <button class="choice-card" style="max-width:230px;font-size:13px;line-height:1.6;text-align:left" onclick="window.chooseEvoPath('${id}',${stageIdx},'${k}')">
          <b style="font-size:15px;color:#7ecbff">${p.name}</b><br><span style="font-weight:400;opacity:.9">${p.desc}</span>
        </button>`).join('')}
    </div>`;
  document.getElementById('overlay').classList.remove('hidden');
}
window.chooseEvoPath = function(id, stageIdx, path){
  if (!EVO_PATHS[path]) return;
  if (!player.skillEvo) player.skillEvo = {};
  if (!player.skillEvo[id]) player.skillEvo[id] = [];
  player.skillEvo[id][stageIdx] = path;
  document.getElementById('overlay').classList.add('hidden');
  addFloat(player.x, player.y-58, `⚡ ${skName(id)} — ${EVO_PATHS[path].name}!`, '#ffd76a', 13);
  AudioSys.sfx('levelup', 0.6);
  addEffect({ type:'ring', x:player.x, y:player.y, r:70, color:'#ffd76a' });
  saveGame(); renderSkillPanel();
};
// Kiểm tra im lặng cho phím Space (không bắn float báo lỗi)
function canCastSilent(id){
  if (!player || dead || id == null || !SKILL_DEFS[id]) return false;
  if ((player.cd[id] || 0) > 0) return false;
  const _inf = skillInfo(id);
  if (!_inf.unlocked) return false;
  if (player.qi < Math.max(1, Math.round(_inf.qi * skMile(id).qi * skEvoMult(id).qi))) return false;
  return true;
}
function milestoneTxt(m){ return m.dmg ? `+${m.dmg*100}% sát thương` : m.cd ? `−${m.cd*100}% hồi chiêu` : `−${m.qi*100}% tiêu hao Mana`; }
window.upgradeSkillUI = function(id){
  const lv = skLv(id);
  if (lv >= 120){ addFloat(player.x, player.y-40, 'Kỹ năng đã đạt cấp tối đa (120)!', '#8a8a8a', 12); return; }
  if (lv >= player.level){ addFloat(player.x, player.y-40, `Cấp kỹ năng ≤ cấp nhân vật (${player.level})`, '#8a8a8a', 12); return; }
  const cost = skUpCost(id), khiCost = skUpKhi(id);
  if (player.silver < cost){ addFloat(player.x, player.y-40, `Cần ${cost.toLocaleString()} Lumen`, '#8a8a8a', 12); return; }
  if ((player.khi || 0) < khiCost){
    const _mn = SK_MILESTONES.find(x => x.lv === lv + 1);
    addFloat(player.x, player.y-40, _mn
      ? `Cấp mốc ${_mn.name} — cần ${khiCost.toLocaleString()} Bản Năng (hạ tinh anh/trùm được nhiều nhất)`
      : `Cần ${khiCost.toLocaleString()} Bản Năng (đánh quái / tĩnh dưỡng ở Suối Ký Ức để tích)`, '#7fd8e0', 12);
    return;
  }
  const _msI = SK_MILESTONES.findIndex(x => x.lv === lv + 1);
  player.silver -= cost;
  player.khi -= khiCost;
  if (!player.skillLv) player.skillLv = {};
  player.skillLv[id] = lv + 1;
  const _ms = _msI >= 0 ? SK_MILESTONES[_msI] : null; // đạt mốc thuần thục của chiêu
  const _evoIdx = _ms ? EVO_LVS.indexOf(_ms.lv) : -1; // 40/80/120 — mốc tiến hóa có chọn nhánh
  if (_ms){
    zoneBanner = { text:'◑ ' + skName(id), sub:`Đạt mốc ${_ms.name} (cấp ${lv+1}) — ${milestoneTxt(_ms)}${_evoIdx >= 0 ? ' · ⚡ CHIÊU THỨC TIẾN HÓA!' : ''}`, color:'#ffb15c', t:3.5 };
    AudioSys.sfx('quest', 0.8);
    addEffect({ type:'ring', x:player.x, y:player.y, r:80, color:'#ffb15c', big:true });
  }
  addFloat(player.x, player.y-52, `⬆ ${skName(id)} → cấp ${lv + 1}!`, '#6ae88a', 13);
  AudioSys.sfx('levelup', 0.4);
  saveGame(); renderSkillPanel();
  if (_evoIdx >= 0) showEvoChoice(id, _evoIdx); // yêu cầu chọn nhánh tiến hóa ngay
};
window.reopenEvoChoiceUI = function(id, stageIdx){ showEvoChoice(id, stageIdx); };
function evoBadgeHtml(id){
  // Huy hiệu nhánh tiến hóa đã chọn (Bá/Tốc mỗi bậc) + nút chọn lại nếu đã đạt mốc mà chưa chọn
  const _stg = evoStage(id), arr = (player.skillEvo && player.skillEvo[id]) || [];
  let out = '';
  for (let i = 0; i < _stg; i++){
    const p = EVO_PATHS[arr[i]];
    if (p) out += `<span style="font-size:9px;color:#ffd76a;margin-right:2px" title="Bậc ${i+1}: ${p.name} — ${p.desc}">${p === EVO_PATHS.power ? '⚔' : '💨'}</span>`;
    else out += `<button class="mini-btn" style="font-size:9px;padding:1px 4px;margin-right:2px;border-color:#7df9ff;color:#7df9ff" title="Chưa chọn nhánh tiến hóa bậc ${i+1} — bấm để chọn" onclick="window.reopenEvoChoiceUI('${id}',${i})">?</button>`;
  }
  return out;
}
function upBtnHtml(id){
  const lv = skLv(id);
  const _spB = `<button class="mini-btn" style="margin-right:3px;${player.spaceSkill === id ? 'border-color:#7df9ff !important;color:#7df9ff !important;' : ''}" title="Gán chiêu này vào phím Space (thay đòn đánh thường; hồi chiêu/thiếu Mana thì tự quay về đòn thường)" onclick="window.assignSpaceUI('${id}')">${player.spaceSkill === id ? '⌨✓' : '⌨'}</button>`;
  if (lv >= 120){
    const _mm = skMile(id), _me = skEvoMult(id);
    const _dPct = Math.round((_mm.dmg * _me.dmg - 1) * 100);
    const _cPct = Math.round((1 - _mm.cd * _me.cd * skCdScale(id)) * 100);
    const _tip = `Đã tối đa 120/120 · +${_dPct}% sát thương · −${_cPct}% hồi chiêu (tính riêng cho chiêu này, gồm cả nhánh tiến hóa đã chọn)`;
    return `${_spB}<span style="font-size:10px;color:#ffd76a;margin-right:4px" title="${_tip}">cấp 120</span>${evoBadgeHtml(id)}`;
  }
  const nm = SK_MILESTONES.find(x => x.lv > lv);
  const cur = [...SK_MILESTONES].reverse().find(x => lv >= x.lv);
  const _msNext = SK_MILESTONES.find(x => x.lv === lv + 1); // cấp kế tiếp có phải cấp mốc không
  const _mult = skMileMult(id);
  const _stg = evoStage(id);
  // 📜 Sách Kỹ Năng: nâng thẳng 1 cấp. Đây là chỗ tiêu MỚI của sách sau khi bỏ "di sản ngoại lớp" —
  // nó không còn mua được chiêu của lớp khác, mà đổ vào chính cây chiêu của lớp mình.
  const _bk = (player.bikipVH || 0) > 0 && lv < 120 && lv < player.level
    ? `<button class="mini-btn" style="margin-right:3px;border-color:#ffb15c;color:#ffb15c" title="Dùng 1 Sách Kỹ Năng nâng thẳng ${skName(id)} lên cấp ${lv+1} (đang có ${player.bikipVH||0} quyển)" onclick="window.useSkillBookUI('${id}')">📜</button>` : '';
  return `${_spB}${_bk}<button class="mini-btn vh-learn-btn" style="margin-right:3px" title="Cấp ${lv}/120${cur ? ' · ' + cur.name : ''} · ⚡tiến hóa bậc ${_stg}/3 (mốc 40/80/120, mỗi mốc chọn nhánh Bá Đạo/Tốc Chiến) — nâng: ${skUpCost(id).toLocaleString()} Lumen + ${skUpKhi(id).toLocaleString()} Bản Năng${_msNext ? ` (cấp mốc ${_msNext.name}: Instinct ×${_mult})` : ''}, +2,5% Sát Thương, −0,25% hồi chiêu${nm ? ` · mốc kế ${nm.name} (cấp ${nm.lv}): ${milestoneTxt(nm)}` : ''} · cấp kỹ năng ≤ cấp nhân vật" onclick="window.upgradeSkillUI('${id}')">⬆${lv}${_stg ? '⚡' + _stg : ''}${_msNext ? '◆' : ''}</button>${evoBadgeHtml(id)}`;
}
window.assignSpaceUI = function(id){
  if (!player) return;
  player.spaceSkill = (player.spaceSkill === id) ? null : id;
  addFloat(player.x, player.y-64, player.spaceSkill ? `⌨ Phím Space → ${skName(id)}` : '⌨ Phím Space → Đòn đánh thường', '#7df9ff', 13);
  AudioSys.sfx('ui', 0.5);
  saveGame(); renderSkillPanel();
};
// Dung Hợp (ghép 2 chiêu liên phái) đã bị cắt hẳn cùng đợt MU-hoá — MU không có khái niệm này.
function vhLearned(id){ return !!(player && player.vohoc && player.vohoc[id]); }
function learnVohoc(id){
  const v = VOHOC_DEFS[id];
  if (!v || vhLearned(id)) return;
  player.vohoc[id] = true;
  calcDerived(); saveGame();
  addFloat(player.x, player.y-66, `✦ Ngộ được: ${v.name}!`, VH_TIER[v.tier].color, 16);
  // Bị động của lớp KHÔNG quy đổi thành %ST (xem CLASS_PASSIVES) — báo đúng thứ nó cho, đừng in
  // "+3,5% Công Kích vĩnh viễn" cho Undying Will rồi để người chơi đi tìm con số đó trong bảng.
  const _pas = CLASS_PASSIVES.includes(id);
  zoneBanner = { text: _pas ? 'BỊ ĐỘNG MỚI' : 'DI SẢN',
    sub: _pas ? `${v.school} · ${v.name} — ${v.desc.replace(/^Bị động:\s*/, '')}`
              : `${v.school} · ${v.name} — +${LEGACY_TIER_PCT[v.tier] || 0}% Công Kích vĩnh viễn (xem ở bảng Kỹ Năng — phím K)`,
    color:VH_TIER[v.tier].color, t:3.5 };
  AudioSys.sfx('quest', 0.9);
}
// ⚠ ĐÃ GỠ: "di sản NGOẠI LỚP". Trước đây Sách Kỹ Năng mua được chiêu của BỐN lớp kia, nên bảng
// Kỹ Năng của một Sylvan Ranger liệt kê Cyclone/Crescent (Dark Knight) và Lightning/Ice/Twister/
// Nova (Dark Wizard) — người chơi mở ra thấy cả bộ chiêu pháp sư trong cây cung thủ. MU Online
// không có khái niệm đó: vũ khí và chiêu thức CHÍNH LÀ bản sắc lớp. Ngoại lệ duy nhất là
// Spellblade, lớp lai, và nó KẾ THỪA sẵn trong bộ chiêu riêng (mg_fireball/mg_powerwave/
// mg_twistingslash) chứ không phải mua bằng sách.
//
// Sách Kỹ Năng nay nâng thẳng một cấp cho chiêu của CHÍNH lớp mình (xem useSkillBookUI) — vẫn là
// tiền tệ có chỗ tiêu, nhưng tiêu vào cây chiêu của mình.
window.useSkillBookUI = function(id){
  if (!player || !SKILL_DEFS[id]) return;
  const lv = skLv(id);
  if (lv >= 120){ addFloat(player.x, player.y-40, 'Kỹ năng đã đạt cấp tối đa (120)!', '#8a8a8a', 12); return; }
  if (lv >= player.level){ addFloat(player.x, player.y-40, `Cấp kỹ năng ≤ cấp nhân vật (${player.level})`, '#8a8a8a', 12); return; }
  if ((player.bikipVH || 0) < 1){ addFloat(player.x, player.y-40, 'Hết Sách Kỹ Năng — rơi từ tinh anh/trùm', '#ffb15c', 12); return; }
  player.bikipVH -= 1;
  if (!player.skillLv) player.skillLv = {};
  player.skillLv[id] = lv + 1;
  addFloat(player.x, player.y-52, `📜 ${skName(id)} → cấp ${lv + 1}`, '#ffb15c', 13);
  AudioSys.sfx('levelup', 0.4);
  const _evoIdx = EVO_LVS.indexOf(lv + 1);
  saveGame(); renderSkillPanel();
  if (_evoIdx >= 0) showEvoChoice(id, _evoIdx);
};
function vhAutoLearn(){ // kỹ năng riêng của lớp tự học khi đạt cấp — mỗi lớp đúng bộ chiêu của mình
  for (const _vid in VOHOC_DEFS){
    const _v = VOHOC_DEFS[_vid];
    if (!_v.phai || vhLearned(_vid) || player.level < _v.unlock) continue;
    if (_v.phai !== player.sect) continue;
    learnVohoc(_vid);
  }
}
function vhKnockback(m, ang, px){
  if (m.def.bossKind) px *= 0.35; // boss nặng cân — khó hất văng
  m.x = clamp(m.x + Math.cos(ang)*px, 30, MAP.w-30);
  m.y = clamp(m.y + Math.sin(ang)*px, 30, MAP.h-30);
}

// ═══════════ VFX TUYỆT CHIÊU — mỗi thần công một hình ảnh riêng, không trùng lặp ═══════════
// VH_VFX: kỹ năng chủ động · style → drawVfx, proj → drawProjStyled.
// SECT_VFX: 16 chiêu riêng của lớp (8 chiêu chính sx_*_a + 8 tuyệt chiêu sx_*_c) — hình ảnh riêng từng lớp
const SECT_VFX = {
  sx_thieulam_a: { style:'bladewhirl',   c2:'#cfe8ff', spin:1.2, dur:0.7 },   // Twisting Slash (Dark Knight) — quét trọn vòng quanh thân
  sx_thieulam_c: { style:'stabburst',    c2:'#cfe8ff', dur:0.85 },            // Death Stab (Dark Knight) — chuỗi nhát đâm liên tiếp
  sx_toanchan_a: { style:'flash',        c2:'#d8f4ff', proj:'arrow' },        // Triple Shot (Sylvan Ranger) — loạt tên bắn tỉa
  // QA: Trấn Phái của Sylvan Ranger là Ice Arrow, nhưng khoá 'icefall' lại nằm ở `_b` — một khoá
  // KHÔNG ai đọc (castSkill chỉ tra sx_<lớp>_a và sx_<lớp>_c). Ice Arrow vì thế chạy 'hexa', tức
  // trận đồ lục tinh còn sót từ bản kiếm hiệp: bắn mũi tên băng mà màn hình hiện một vòng sao.
  sx_toanchan_c: { style:'icefall',      c2:'#dff4ff', dur:1.0 },             // Ice Arrow (Sylvan Ranger) — phiến băng kết trên cao rồi rơi xuống vỡ
  sx_baidasan_a: { style:'poisonbloom',  c2:'#b8ff9a', proj:'serpent', dur:1.1 }, // Poison (Dark Wizard) — vũng độc loang ra, sủi bọt
  sx_baidasan_c: { style:'meteor',       c2:'#ffcf7a' },                      // Meteorite (Dark Wizard) — vẫn thạch lửa giáng thế
  sx_minhgiao_a: { style:'fireslash',    c2:'#ffcf7a' },                      // Fire Slash (Spellblade) — đao quang cuốn lửa
  sx_minhgiao_c: { style:'flamewall',    c2:'#ff9a5a', dur:1.15 },            // Flame Strike (Spellblade) — hàng cột lửa dựng lên phía trước
  // QA: Dark Lord (sect id 'bug') chưa từng có entry nào ở đây — cả chiêu chính lẫn Trấn Phái đều rơi
  // về style mặc định chung chung, là lớp DUY NHẤT không có hình ảnh nhận diện riêng khi tung chiêu.
  sx_bug_a:      { style:'windslash',    c2:'#d0e07a' },                      // Force Wave (Dark Lord) — sóng chấn quyền trượng
  sx_bug_c:      { style:'firepillar',   c2:'#ffb15c', dur:1.15 },            // Fire Scream (Dark Lord) — ba vệt lửa chạy ra rồi dựng cột lửa
  sx_vophai_a:   { style:'fist',         c2:'#e8d8a8' },                      // Hatchling Strike (Unclassed) — cú đấm trần, chưa có binh khí
  sx_vophai_c:   { style:'stormhost',    c2:'#e4ebff' },                      // Wanderer's Resolve (Unclassed) — dồn hết sức vào một đòn
};
// VH_VFX: hình ảnh riêng cho chiêu Sổ Kỹ Năng. Sau đợt MU-hoá chỉ còn Dark Raven cần entry
// riêng (các style khác đã gắn thẳng vào SECT_VFX theo lớp).
const VH_VFX = {
  // Năm ô BUFF trước đây không khai style nào cả nên cùng rơi về 'vajra': bấm buff của lớp nào
  // cũng ra đúng một vòng ấn quay. Nay mỗi lớp một hình theo đúng thứ nó làm.
  gangkhi:         { style:'seal4',     c2:'#cfe8ff', dur:0.9 },  // Defense (Dark Knight) — ấn khiên bốn phương
  elf_greaterdmg:  { style:'sunwheel',  c2:'#fff0be', dur:1.1 },  // Bless (Sylvan Ranger) — vòng sáng ban phước
  dw_shield:       { style:'hexa',      c2:'#cfe8ff', dur:1.0, spin:1.2 }, // Soul Barrier (Dark Wizard) — lồng lục giác
  mg_battlefury:   { style:'phoenix',   c2:'#ffcf7a', dur:1.1 },  // Battle Fury (Spellblade) — song dực liệt hỏa
  dl_commandaura:  { style:'galaxy',    c2:'#ffb0a0', dur:1.1, spin:1.4 }, // Increase Critical Damage (Dark Lord) — hào quang chỉ huy xoay quanh
  // Bốn TUYỆT CHIÊU ô 4 (xem SIGNATURE_SKILL) — mỗi chiêu một hình riêng, không dùng chung style
  // mặc định theo kiểu chiêu nữa. Tuyệt chiêu mà bung ra y hệt chiêu thường thì không ai nhớ nổi.
  dw_evilspirit:    { style:'spiritdragon', c2:'#cfffc0', dur:1.2 }, // hai rồng bóng tối cuộn quanh rồi lao ra
  dw_lightning:     { style:'boltdown',    c2:'#eaffb0', dur:0.75 }, // sét giáng từ trên trời xuống
  dw_nova:          { style:'novaburst',   c2:'#fff0b0', dur:1.3 },  // dồn năng lượng rồi mới bung
  dw_ice:           { style:'icefall',     c2:'#dff4ff', dur:1.0 },  // phiến băng rơi xuống vỡ tan
  dl_electricspark: { style:'boltdown',    c2:'#fff3a0', dur:0.75 }, // sét giáng, tia con nảy ra
  mg_flamestrike:   { style:'flamewall',   c2:'#ff9a5a', dur:1.15 }, // hàng cột lửa phía trước
  dk_ragefulblow:   { style:'groundburst', c2:'#cfe8ff', dur:0.9 },  // nền toác thành tia từ điểm giáng
  mg_powerslash:    { style:'lightwave',   c2:'#ffe9b0', dur:0.85 }, // sóng sáng rời kiếm bay đi
  dl_chaoticdiseier:{ style:'quakeburst',  c2:'#e8c88a', dur:1.0 },  // Earthquake — nền nứt thành vòng, đá bắn lên
  elf_penetration:  { style:'flash',       c2:'#dfffff', proj:'lance' }, // mũi tên xuyên — xem drawProjStyled
};
function _vxLine(x1, y1, x2, y2){ ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); }
function _vxBolt(x, y, ang, len, w, col){
  ctx.strokeStyle = col; ctx.lineWidth = 2.6; ctx.globalAlpha = Math.min(1, ctx.globalAlpha);
  ctx.beginPath(); ctx.moveTo(x, y);
  const n = 6;
  for (let i = 1; i <= n; i++){
    const t = i / n, off = (i < n ? rnd(-w, w) : 0);
    ctx.lineTo(x + Math.cos(ang)*len*t + Math.cos(ang + Math.PI/2)*off, y + Math.sin(ang)*len*t + Math.sin(ang + Math.PI/2)*off);
  }
  ctx.stroke();
  ctx.lineWidth = 1.1; ctx.strokeStyle = '#fff'; ctx.stroke();
}
function _vxSword(x, y, ang, len, col, al){
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang); ctx.globalAlpha = al;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(2, 0); ctx.lineTo(len*0.78, -3.2); ctx.lineTo(len, 0); ctx.lineTo(len*0.78, 3.2); ctx.closePath(); ctx.fill();
  ctx.fillRect(-7, -1.6, 9, 3.2); ctx.fillRect(-1.5, -6.5, 3, 13);
  ctx.restore();
}
function _vxPetal(x, y, rot, s, col, al){
  ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.globalAlpha = al; ctx.fillStyle = col;
  ctx.beginPath(); ctx.ellipse(0, 0, s, s*0.45, 0, 0, 7); ctx.fill(); ctx.restore();
}
function _vxFlake(x, y, s, col, al){
  ctx.strokeStyle = col; ctx.lineWidth = 1.6; ctx.globalAlpha = al;
  for (let i = 0; i < 3; i++){ const a = i*Math.PI/3; _vxLine(x - Math.cos(a)*s, y - Math.sin(a)*s, x + Math.cos(a)*s, y + Math.sin(a)*s); }
}
function _vxGlyph(x, y, ch, s, col, al){
  ctx.globalAlpha = al; ctx.font = `bold ${Math.round(s)}px "Noto Serif", serif`; ctx.textAlign = 'center';
  ctx.strokeStyle = 'rgba(0,0,0,.55)'; ctx.lineWidth = 3; ctx.strokeText(ch, x, y + s*0.35);
  ctx.fillStyle = col; ctx.fillText(ch, x, y + s*0.35);
}
// ── Khối dựng hình cho hoạt ảnh chiêu ────────────────────────────────────────────────────
// Bản đồ vẽ theo lối 2,5D: nhân vật và quái đứng THẲNG trên điểm chân của chúng. Nên một cột
// lửa "dựng lên" chính là ngọn lửa vẽ từ điểm chân đi NGƯỢC LÊN trên màn hình — đúng như trong
// MU, nơi Fire Scream và Flame Strike đều phun cột lửa chứ không phải loang một vòng dưới đất.
// kk là tiến độ mọc lên 0→1; qua 1 thì cột đứng nguyên độ cao và chỉ còn lay động.
function _vxFlameCol(x, gy, h, w, kk, ph, c1, c2, al){
  const H = h * Math.min(1, kk);
  if (H < 2) return;
  const lay = (t) => Math.sin(ph + t*5.5) * w * 0.34 * t;   // càng lên cao càng lắc mạnh
  const than = (ww, col, aa) => {
    ctx.globalAlpha = aa; ctx.fillStyle = col;
    ctx.beginPath(); ctx.moveTo(x - ww, gy);
    for (let i = 1; i <= 6; i++){                            // mép trái, uốn theo chiều cao
      const t = i/6; ctx.lineTo(x - ww*(1 - t*0.82) + lay(t), gy - H*t);
    }
    for (let i = 6; i >= 1; i--){                            // mép phải, đi ngược xuống
      const t = i/6; ctx.lineTo(x + ww*(1 - t*0.82) + lay(t), gy - H*t);
    }
    ctx.closePath(); ctx.fill();
  };
  than(w,        c1, al*0.55);                               // quầng ngoài
  than(w*0.66,   c2, al*0.98);                               // thân lửa
  than(w*0.28, '#fff6d0', al);                               // lõi trắng nóng
  ctx.globalAlpha = al*0.5; ctx.fillStyle = c2;              // vũng sáng dưới chân cột
  ctx.beginPath(); ctx.ellipse(x, gy, w*1.15, w*0.42, 0, 0, 7); ctx.fill();
  for (let i = 0; i < 3; i++){                               // tàn lửa bay lên khỏi ngọn
    const t = ((kk*1.5 + i*0.37) % 1);
    ctx.globalAlpha = al*(1 - t)*0.85; ctx.fillStyle = i % 2 ? '#fff6d0' : c2;
    ctx.beginPath(); ctx.arc(x + Math.sin(ph + i*2.1)*w*0.7, gy - H - t*h*0.45, 2.6*(1-t) + 1, 0, 7); ctx.fill();
  }
  ctx.globalAlpha = 1;
}
// Thân rồng cuộn: một chuỗi đốt chạy dọc cung tròn, đốt to ở đầu và thuôn dần về đuôi.
// a0 là góc của ĐẦU rồng, coil là số radian thân trải ra phía sau nó.
function _vxDragon(cx, cy, a0, rr, coil, seg, sz, c1, c2, al){
  const pt = (t) => {                                        // t=0 là đầu, t=1 là chót đuôi
    const ang = a0 + coil*t, r2 = rr*(1 - t*0.16);
    return [cx + Math.cos(ang)*r2, cy + Math.sin(ang)*r2*0.72];
  };
  // THÂN TỐI, VIỀN SÁNG. Bản đầu tô đốt bằng chính màu chiêu: Evil Spirit màu lục nhạt trên bản đồ
  // tân thủ cũng lục nhạt, nên cả con rồng chìm nghỉm — quay phim lại mới thấy nó vẫn ở đó suốt.
  // Rồng bóng tối thì thân vốn phải tối; màu chiêu chuyển hết sang viền, đọc được trên mọi nền.
  ctx.globalAlpha = al*0.9;
  for (let i = seg; i >= 1; i--){                            // vẽ từ đuôi lên đầu để đầu nằm trên
    const t = i/seg, [px, py] = pt(t), rs = sz*(1 - t*0.72);
    ctx.fillStyle = '#100d18';
    ctx.beginPath(); ctx.arc(px, py, rs, 0, 7); ctx.fill();
    ctx.strokeStyle = i % 2 ? c1 : c2; ctx.lineWidth = Math.max(1.4, rs*0.32);
    ctx.beginPath(); ctx.arc(px, py, rs, 0, 7); ctx.stroke();
  }
  const [hx, hy] = pt(0), [nx, ny] = pt(0.16);
  const ha = Math.atan2(hy - ny, hx - nx);                   // đầu hướng theo chiều bay
  ctx.save(); ctx.translate(hx, hy); ctx.rotate(ha); ctx.scale(1.45, 1.45);
  ctx.globalAlpha = al;
  ctx.beginPath();                                            // hàm rồng: mõm nhọn, gáy phình
  ctx.moveTo(sz*2.1, 0);
  ctx.lineTo(sz*0.5, -sz*0.95); ctx.lineTo(-sz*0.7, -sz*0.75);
  ctx.lineTo(-sz*0.7, sz*0.75); ctx.lineTo(sz*0.5, sz*0.95);
  ctx.closePath();
  ctx.fillStyle = '#100d18'; ctx.fill();
  ctx.strokeStyle = c1; ctx.lineWidth = sz*0.38; ctx.lineJoin = 'round'; ctx.stroke();
  for (const sy of [-1, 1]){                                  // hai sừng ngả về sau
    ctx.beginPath(); ctx.moveTo(-sz*0.2, sy*sz*0.7);
    ctx.lineTo(-sz*1.6, sy*sz*1.6); ctx.lineTo(-sz*0.4, sy*sz*0.35); ctx.closePath();
    ctx.fillStyle = c2; ctx.fill();
  }
  ctx.fillStyle = '#fff';                                     // mắt
  ctx.beginPath(); ctx.arc(sz*0.55, -sz*0.32, sz*0.26, 0, 7); ctx.fill();
  ctx.restore();
  ctx.globalAlpha = 1;
}
function drawVfx(e, k, a){
  const S = e.style, X = e.x, Y = e.y, F = e.face || 0, R = e.r || 100, C1 = e.c1 || '#fff', C2 = e.c2 || '#fff', G = e.glyph || '✦';
  const spin = e.ang || 0;
  ctx.save(); ctx.lineCap = 'round';
  const arc  = (x, y, r, a0, a1, c, w, al) => { ctx.strokeStyle = c; ctx.lineWidth = w; ctx.globalAlpha = al; ctx.beginPath(); ctx.arc(x, y, Math.max(1, r), a0, a1); ctx.stroke(); };
  const disc = (x, y, r, c, al) => { ctx.fillStyle = c; ctx.globalAlpha = al; ctx.beginPath(); ctx.arc(x, y, Math.max(0.5, r), 0, 7); ctx.fill(); };
  const poly = (x, y, r, n, rot, c, w, al) => { ctx.strokeStyle = c; ctx.lineWidth = w; ctx.globalAlpha = al; ctx.beginPath(); for (let i = 0; i <= n; i++){ const aa = rot + i*2*Math.PI/n; i ? ctx.lineTo(x + Math.cos(aa)*r, y + Math.sin(aa)*r) : ctx.moveTo(x + Math.cos(aa)*r, y + Math.sin(aa)*r); } ctx.stroke(); };
  if (S === 'flash'){ // tia sáng xuất chiêu (proj)
    arc(X, Y, R*(0.4 + k*0.7), F - 1, F + 1, C1, 5*(1-k) + 2, a*0.9);
    _vxGlyph(X + Math.cos(F)*R*0.5, Y + Math.sin(F)*R*0.5, G, 20, C2, a*0.9);
  } else if (S === 'shock'){ // vòng đệm chung
    arc(X, Y, R*(0.2 + k*0.8), 0, 7, C1, 4, a*0.8);
    arc(X, Y, R*0.55*(0.3 + k*0.7), 0, 7, C2, 2.5, a*0.6);
  } else if (S === 'vortex'){ // Hấp Tinh / Bắc Minh — hắc động xoáy hút vào
    const rr = R*(1.05 - k*0.5);
    disc(X, Y, R*0.32*(1 - k*0.4), C2, a*0.55);
    for (let i = 0; i < 5; i++){ const a0 = i*1.2566 + spin + k*6; arc(X, Y, rr, a0, a0 + 1.4, C1, 4.5, a*0.9); }
    arc(X, Y, rr*0.6, spin - k*8, spin - k*8 + 4, C2, 2.5, a*0.7);
    _vxGlyph(X, Y, G, 24, C1, a*0.9);
  } else if (S === 'fist'){ // Thất Thương / La Hán / Liên Hoa — sóng quyền đứt quãng chồng lớp
    for (let i = 0; i < 4; i++){ const kk = k*1.3 - i*0.12; if (kk <= 0) continue;
      ctx.setLineDash([10, 7]); arc(X, Y, R*(0.25 + Math.min(1, kk)*0.75)*(1 - i*0.12), F - 0.7, F + 0.7, i%2 ? C2 : C1, 6 - i, a*0.85); }
    ctx.setLineDash([]);
    _vxGlyph(X + Math.cos(F)*R*0.55, Y + Math.sin(F)*R*0.55, G, 30, C2, a);
  } else if (S === 'frost'){ // Huyền Minh — mảnh băng nhọn xé không khí
    for (let i = 0; i < 9; i++){ const ang = F + (i-4)*0.22; const L = R*(0.35 + k*0.65)*(0.75 + ((i*37)%10)/22);
      const tx = X + Math.cos(ang)*L, ty = Y + Math.sin(ang)*L;
      ctx.fillStyle = i%2 ? C1 : C2; ctx.globalAlpha = a*0.85; ctx.beginPath();
      ctx.moveTo(tx + Math.cos(ang)*12, ty + Math.sin(ang)*12);
      ctx.lineTo(tx + Math.cos(ang + 2.4)*7, ty + Math.sin(ang + 2.4)*7);
      ctx.lineTo(tx + Math.cos(ang - 2.4)*7, ty + Math.sin(ang - 2.4)*7); ctx.closePath(); ctx.fill(); }
    arc(X, Y, R*(0.3 + k*0.5), F - 1, F + 1, C2, 2.5, a*0.7);
  } else if (S === 'sunwheel'){ // Cửu Dương / Thuần Dương — mặt trời tia sáng quay
    const rr = R*(0.55 + k*0.3);
    arc(X, Y, rr, 0, 7, C1, 5, a*0.9);
    for (let i = 0; i < 12; i++){ const aa = i*0.5236 + spin; ctx.strokeStyle = C2; ctx.lineWidth = 3; ctx.globalAlpha = a*0.8;
      _vxLine(X + Math.cos(aa)*(rr + 6), Y + Math.sin(aa)*(rr + 6), X + Math.cos(aa)*(rr + 16*(1-k) + 8), Y + Math.sin(aa)*(rr + 16*(1-k) + 8)); }
    _vxGlyph(X, Y, G, 30, C2, a);
  } else if (S === 'dragonwave'){ // Long Tượng / Thái Cực / Hàng Long — long ảnh cuộn sóng
    for (let j = 0; j < 3; j++){ ctx.strokeStyle = j ? C2 : C1; ctx.lineWidth = 5 - j*1.3; ctx.globalAlpha = a*0.85; ctx.beginPath();
      for (let i = 0; i <= 20; i++){ const t = i/20; const xx = X - R*0.9 + t*R*1.8; const yy = Y + Math.sin(t*9 + j*1.3 + k*7)*R*0.28*(1 + t*0.4);
        i ? ctx.lineTo(xx, yy) : ctx.moveTo(xx, yy); } ctx.stroke(); }
    _vxGlyph(X, Y - R*0.4, G, 30, C2, a*0.9);
  } else if (S === 'crescents'){ // Hồ Gia / Võ Đang — trăng lưỡi liềm chồng nhau
    for (let i = 0; i < 3; i++){ arc(X, Y, R*(0.35 + k*0.6) + i*14, F - 0.85, F + 0.85, i%2 ? C2 : C1, 6 - i*1.5, a*0.9); }
  } else if (S === 'petals'){ // Chiết Mai / Bích Ba — cánh hoa cuốn thành chưởng ấn
    for (let i = 0; i < 10; i++){ const ang = F + (i - 4.5)*0.19; const L = R*(0.2 + k*0.75)*(0.7 + ((i*53)%10)/20);
      _vxPetal(X + Math.cos(ang)*L, Y + Math.sin(ang)*L, ang + k*5, 5.5, i%2 ? C1 : C2, a*0.85); }
    _vxGlyph(X + Math.cos(F)*R*0.5, Y + Math.sin(F)*R*0.5, G, 22, C2, a*0.7);
  } else if (S === 'suns'){ // Lục Dương / Đả Cẩu — quang cầu li hoan quanh người
    for (let i = 0; i < 6; i++){ const aa = i*1.0472 + spin + k*4; const rr = R*(0.25 + k*0.55);
      const ox = X + Math.cos(aa)*rr, oy = Y + Math.sin(aa)*rr*0.8;
      disc(ox, oy, 9*(1-k) + 4, i%2 ? C1 : C2, a*0.9); disc(ox, oy, 3, '#fff', a); }
    arc(X, Y, R*(0.3 + k*0.65), 0, 7, C1, 3.5, a*0.6);
  } else if (S === 'hexa'){ // Bát Hoang / Bát Quái — trận đồ lục tinh
    const rr = R*(0.5 + k*0.35);
    poly(X, Y, rr, 3, spin, C1, 3.5, a*0.9); poly(X, Y, rr, 3, spin + Math.PI/3, C2, 3.5, a*0.9);
    for (let i = 0; i < 6; i++){ const aa = i*1.0472 + spin; disc(X + Math.cos(aa)*rr, Y + Math.sin(aa)*rr, 3.5, C2, a*0.8); }
    _vxGlyph(X, Y, G, 22, C1, a);
  } else if (S === 'bonemist'){ // Hóa Cốt — miên chưởng sương xương trắng xám
    for (let i = 0; i < 7; i++){ const ang = F + (i-3)*0.3; const L = R*(0.25 + k*0.6)*(0.8 + ((i*29)%10)/25);
      disc(X + Math.cos(ang)*L, Y + Math.sin(ang)*L, 10*(1-k) + 4, i%2 ? C1 : C2, a*0.4); }
    for (let i = 0; i < 3; i++){ const ang = F + (i-1)*0.5; ctx.strokeStyle = C2; ctx.lineWidth = 2.5; ctx.globalAlpha = a*0.8;
      _vxLine(X + Math.cos(ang)*R*0.2, Y + Math.sin(ang)*R*0.2, X + Math.cos(ang)*R*(0.4 + k*0.5), Y + Math.sin(ang)*R*(0.4 + k*0.5)); }
  } else if (S === 'vajra'){ // Kim Cang / Kiếm Xoáy — kim cang phạn ấn quay
    poly(X, Y, R*(0.45 + k*0.2), 4, spin, C1, 4, a*0.9);
    poly(X, Y, R*(0.45 + k*0.2), 4, spin + Math.PI/4, C2, 2.5, a*0.7);
    disc(X, Y, 8, C2, a*0.8); _vxGlyph(X, Y, G, 22, C1, a);
  } else if (S === 'galaxy'){ // Thái Huyền / Vô Tướng — tinh hà vận chuyển
    for (let i = 0; i < 14; i++){ const aa = i*0.4488 + spin; const rr = R*(0.2 + ((i*31)%10)/10*0.7)*(0.6 + k*0.4);
      disc(X + Math.cos(aa)*rr, Y + Math.sin(aa)*rr, 1.8 + ((i*17)%3), i%3 ? C2 : C1, a*0.9); }
    arc(X, Y, R*0.5, spin, spin + 4.5, C1, 3, a*0.7);
    _vxGlyph(X, Y, G, 26, C2, a);
  } else if (S === 'demonburst'){ // Thiên Ma / Cáp Mô — ma hỏa phóng từ mặt đất
    for (let i = 0; i < 8; i++){ const aa = i*0.7854; const L = R*(0.35 + k*0.6)*(i%2 ? 1 : 0.7);
      ctx.fillStyle = i%2 ? C2 : C1; ctx.globalAlpha = a*0.85; ctx.beginPath();
      ctx.moveTo(X + Math.cos(aa - 0.14)*R*0.25, Y + Math.sin(aa - 0.14)*R*0.25);
      ctx.lineTo(X + Math.cos(aa)*L, Y + Math.sin(aa)*L);
      ctx.lineTo(X + Math.cos(aa + 0.14)*R*0.25, Y + Math.sin(aa + 0.14)*R*0.25); ctx.closePath(); ctx.fill(); }
    _vxGlyph(X, Y, G, 26, C2, a);
  } else if (S === 'devourmaw'){ // Phệ Thiên — miệng quái nuốt mục tiêu
    disc(X, Y, R*(0.4 + k*0.15), C2, a*0.6);
    for (let i = 0; i < 10; i++){ const aa = i*0.628 + spin + k*3; const rr = R*(0.42 + k*0.1);
      const tx = X + Math.cos(aa)*rr, ty = Y + Math.sin(aa)*rr;
      ctx.fillStyle = '#fff'; ctx.globalAlpha = a*0.85; ctx.beginPath();
      ctx.moveTo(tx, ty); ctx.lineTo(tx + Math.cos(aa + 0.3)*7, ty + Math.sin(aa + 0.3)*7); ctx.lineTo(tx + Math.cos(aa - 0.3)*7, ty + Math.sin(aa - 0.3)*7); ctx.closePath(); ctx.fill(); }
    arc(X, Y, R*(0.55 + k*0.15), spin, spin + 5, C1, 4, a*0.8);
  } else if (S === 'bloodclaw'){ // Huyết Ma / Hắc Nguyệt Bạch Cốt Trảo / Trảm Ma — trảo huyết 3 nhát
    for (let i = 0; i < 3; i++){ const off = (i-1)*0.35; arc(X, Y, R*(0.4 + k*0.55) + i*12, F + off - 0.55, F + off + 0.55, i === 1 ? C2 : C1, 5, a*0.9); }
    for (let i = 0; i < 6; i++){ const ang = F + (i - 2.5)*0.4; const L = R*(0.3 + k*0.6); disc(X + Math.cos(ang)*L, Y + Math.sin(ang)*L, 2.5, C1, a*0.8); }
  } else if (S === 'swordride'){ // Ngự Kiếm — kiếm quang xé gió + tàn ảnh
    const x0 = e.x0 != null ? e.x0 : X, y0 = e.y0 != null ? e.y0 : Y;
    for (let i = 0; i < 3; i++){ const t = i/3; _vxSword(x0 + (X-x0)*t, y0 + (Y-y0)*t, F, 30, i ? C2 : C1, a*(1 - t*0.5)); }
    ctx.strokeStyle = C1; ctx.lineWidth = 6; ctx.globalAlpha = a*0.9; _vxLine(x0, y0, X, Y);
    ctx.strokeStyle = C2; ctx.lineWidth = 2; _vxLine(x0, y0, X, Y);
  } else if (S === 'wuxing'){ // vòng nguyên tố — 5 sắc quang xoay
    const x0 = e.x0 != null ? e.x0 : X, y0 = e.y0 != null ? e.y0 : Y;
    const cols = [C1, C2, '#ffd76a', '#8ae8c8', '#ff9ae0'];
    for (let i = 1; i <= 5; i++){ const t = i/5; arc(x0 + (X-x0)*t, y0 + (Y-y0)*t, 10 + 6*(1-k), F - 0.9, F + 0.9, cols[i-1], 4, a*0.85); }
  } else if (S === 'thunderpillar'){ // Cửu Thiên Huyền Lôi — lôi trụ giáng thế
    for (let i = 0; i < 3; i++){ const aa = F + i*2.094 + 0.5; const px = X + Math.cos(aa)*R*0.55, py = Y + Math.sin(aa)*R*0.55;
      _vxBolt(px, py - R*0.7, Math.PI/2, R*0.7, R*0.14, i%2 ? C2 : C1); }
    arc(X, Y, R*(0.3 + k*0.6), 0, 7, C1, 3, a*0.6);
  } else if (S === 'phoenix'){ // Hỏa Phượng / Thánh Hỏa — song dực liệt hỏa + tro lửa
    arc(X - R*0.25, Y, R*(0.3 + k*0.5), Math.PI*0.95, Math.PI*1.85, C1, 6, a*0.9);
    arc(X + R*0.25, Y, R*(0.3 + k*0.5), Math.PI*1.15, Math.PI*2.05, C1, 6, a*0.9);
    for (let i = 0; i < 10; i++){ const t = ((i*37)%10)/10; disc(X + Math.sin(i*2.3 + k*8)*R*0.4, Y + R*0.3 - t*R*(0.6 + k*0.4), 2.5, i%2 ? C1 : C2, a*0.8); }
    _vxGlyph(X, Y, G, 24, C2, a);
  } else if (S === 'icecage'){ // Huyền Băng — hàn khí kết tinh
    ctx.fillStyle = C2; ctx.globalAlpha = a*0.25; ctx.beginPath(); ctx.moveTo(X, Y); ctx.arc(X, Y, R*(0.4 + k*0.55), F - 0.9, F + 0.9); ctx.closePath(); ctx.fill();
    for (let i = 0; i < 6; i++){ const ang = F + (i - 2.5)*0.3; const L = R*(0.3 + k*0.6); _vxFlake(X + Math.cos(ang)*L, Y + Math.sin(ang)*L, 6*(1-k) + 3, i%2 ? C1 : C2, a*0.9); }
  } else if (S === 'seal4'){ // Ấn Trấn — vuông ấn + bốn dấu bốn phương
    poly(X, Y, R*(0.45 + k*0.25), 4, Math.PI/4, C1, 4, a*0.9);
    const bs = ['★', '◆', '▲', '⚔'];
    for (let i = 0; i < 4; i++){ const aa = i*Math.PI/2 - Math.PI/2; _vxGlyph(X + Math.cos(aa)*R*0.5, Y + Math.sin(aa)*R*0.5, bs[i], 18, C2, a*(1 - k*0.5)); }
    disc(X, Y, 6, C1, a*0.9);
  } else if (S === 'icefield'){ // Băng Phong — băng nguyên phủ sóng
    disc(X, Y, R*(0.4 + k*0.6), C2, a*0.18);
    arc(X, Y, R*(0.4 + k*0.6), 0, 7, C1, 4, a*0.85);
    for (let i = 0; i < 8; i++){ const aa = i*0.7854 + 0.4; _vxFlake(X + Math.cos(aa)*R*(0.5 + k*0.4), Y + Math.sin(aa)*R*(0.5 + k*0.4), 5, i%2 ? C1 : C2, a*0.8); }
  } else if (S === 'stormhost'){ // Lôi Đình — vạn quân sấm tỏa
    for (let i = 0; i < 7; i++){ _vxBolt(X, Y, i*0.8976 + 0.3, R*(0.35 + k*0.6), R*0.1, i%2 ? C1 : C2); }
    arc(X, Y, R*0.4*(1 + k), 0, 7, C2, 2.5, a*0.5);
  } else if (S === 'buddhapalm'){ // Niết Bàn — phật chưởng giáng thế
    const pr = R*(0.4 + k*0.5);
    ctx.fillStyle = C1; ctx.globalAlpha = a*0.85;
    ctx.beginPath(); ctx.ellipse(X, Y, pr*0.42, pr*0.5, 0, 0, 7); ctx.fill();
    for (let i = 0; i < 5; i++){ const fx = X + (i-2)*pr*0.2; const fl = pr*(0.34 + (i === 2 ? 0.12 : (i%2 ? 0.04 : 0)));
      ctx.beginPath(); ctx.ellipse(fx, Y - pr*0.5 - fl*0.5, pr*0.085, fl*0.55, 0, 0, 7); ctx.fill(); }
    _vxGlyph(X, Y, '✦', pr*0.5, C2, a);
  } else if (S === 'windslash'){ // Twisting Slash (Dark Knight) — chém xoáy cuốn gió
    const rr = R*(0.35 + k*0.55);
    arc(X, Y, rr, F - 0.95, F + 0.95, C1, 6*(1 - k*0.4), a*0.9);
    for (let i = 0; i < 4; i++){
      const wa = F + (i - 1.5)*0.35, L1 = rr*0.55, L2 = rr*(0.95 + i*0.05);
      ctx.strokeStyle = C2; ctx.lineWidth = 2; ctx.globalAlpha = a*0.7;
      ctx.beginPath();
      for (let s2 = 0; s2 <= 8; s2++){ const tt = s2/8; const ang2 = wa + tt*0.6*(i%2 ? 1 : -1); const rL = L1 + (L2-L1)*tt;
        const px = X + Math.cos(ang2)*rL, py = Y + Math.sin(ang2)*rL; s2 ? ctx.lineTo(px, py) : ctx.moveTo(px, py); }
      ctx.stroke();
    }
    _vxGlyph(X + Math.cos(F)*rr*0.6, Y + Math.sin(F)*rr*0.6, G, 22, C2, a*0.85);
  } else if (S === 'fireslash'){ // Fire Slash (Spellblade) — đao quang cuốn lửa
    const rr = R*(0.35 + k*0.6);
    arc(X, Y, rr, F - 0.8, F + 0.8, C1, 7*(1 - k*0.3), a*0.9);
    arc(X, Y, rr*0.92, F - 0.7, F + 0.7, '#fff2c0', 2, a*0.8);
    for (let i = 0; i < 6; i++){ const t2 = i/6; const ang2 = F + (t2 - 0.5)*1.5;
      const ex = X + Math.cos(ang2)*rr, ey = Y + Math.sin(ang2)*rr - t2*6;
      disc(ex, ey - 4, 3.5*(1 - t2*0.4), i%2 ? C1 : C2, a*0.75); }
    _vxGlyph(X + Math.cos(F)*rr*0.6, Y + Math.sin(F)*rr*0.6, G, 22, C2, a*0.85);
  } else if (S === 'meteor'){ // Meteor (Dark Wizard) — vẫn thạch lửa giáng thế, nổ tung khi chạm đất
    for (let i = 0; i < 6; i++){
      const seed = i*53.7;
      const fx0 = X + Math.cos(seed)*R*0.6, fy0 = Y - R*(1.05 + (i%3)*0.22);
      const tx = X + Math.cos(seed + 1.7)*R*0.3, ty = Y + Math.sin(seed + 1.7)*R*0.2;
      const kk = Math.min(1, k*1.4 - i*0.09); if (kk <= 0) continue;
      const px = fx0 + (tx-fx0)*kk, py = fy0 + (ty-fy0)*kk;
      ctx.strokeStyle = C1; ctx.lineWidth = 4; ctx.globalAlpha = a*0.7;
      _vxLine(px, py, px - (tx-fx0)*0.18, py - (ty-fy0)*0.18);
      disc(px, py, 7*(1 - kk*0.3), C1, a*0.9); disc(px, py, 3.2, C2, a);
      if (kk >= 0.94) arc(tx, ty, 14 + (k - 0.75)*90, 0, 7, C2, 4, a*0.85);
    }
    disc(X, Y, R*(0.22 + k*0.35), C1, a*0.22);
    _vxGlyph(X, Y - R*0.1, G, 26, C2, a*0.9);
  } else if (S === 'bladewhirl'){ // Twisting Slash — lưỡi kiếm quét trọn vòng, ba lớp lệch pha
    // Chiêu này là "xoay tít vũ khí quanh thân", nên hình phải là VÒNG KHÉP KÍN chứ không phải
    // nhát chém một hướng — style windslash cũ chỉ vẽ về phía mặt, mất hẳn ý nghĩa quét cả vòng.
    for (let i = 0; i < 3; i++){
      const a0 = spin + k*9 + i*2.09, rr = R*(0.5 + k*0.55) * (1 - i*0.13);
      ctx.beginPath();
      ctx.arc(X, Y, rr, a0, a0 + 1.5);
      ctx.arc(X, Y, rr*0.62, a0 + 1.5, a0, true);
      ctx.closePath();
      // Viền tối trước rồi mới tô: bản đầu chỉ tô màu lớp ở alpha thấp, mà bản đồ tân thủ nền xanh
      // lá sáng trưng nên cả ba lưỡi quét chìm nghỉm — trong game gần như không thấy chiêu bung ra.
      ctx.strokeStyle = 'rgba(10,8,18,.55)'; ctx.lineWidth = 2.5; ctx.globalAlpha = a*0.8; ctx.stroke();
      ctx.fillStyle = i === 1 ? C2 : C1; ctx.globalAlpha = a*(0.95 - i*0.16); ctx.fill();
    }
    arc(X, Y, R*(0.5 + k*0.55), 0, 7, C2, 2, a*0.35);
    for (let i = 0; i < 6; i++){ const aa = i*1.047 + spin - k*4;   // mạt kim loại văng ra
      disc(X + Math.cos(aa)*R*(0.7 + k*0.5), Y + Math.sin(aa)*R*(0.7 + k*0.5), 2.4*(1-k), '#fff', a*0.7); }

  } else if (S === 'spiritswarm'){ // Evil Spirit — bầy u linh lượn quanh rồi bổ nhào vào trong
    disc(X, Y, R*(0.55 + k*0.3), '#0c1408', a*0.3);
    for (let i = 0; i < 7; i++){
      const aa = i*0.898 + spin + k*3.4;
      const rr = R*(1.0 - k*0.62);                                   // lượn vào tâm theo thời gian
      const cx = X + Math.cos(aa)*rr, cy = Y + Math.sin(aa)*rr*0.78;
      ctx.save(); ctx.translate(cx, cy); ctx.globalAlpha = a*0.9;
      // Kích thước phải theo R. Bản đầu để cứng 9px, mà chiêu này bán kính 150 — bảy con u linh
      // 9px rải trên vòng 150px thì trong game không nhìn ra gì ngoài mấy chấm mờ.
      const sz = R*0.15 + Math.sin(i*2 + k*10)*R*0.02;
      ctx.fillStyle = i % 2 ? C1 : C2;                               // thân u linh: chóp nhọn, vạt rách
      ctx.beginPath();
      ctx.moveTo(0, -sz);
      ctx.quadraticCurveTo(sz*0.62, -sz*0.5, sz*0.6, sz*0.2);
      ctx.lineTo(sz*0.3, sz*0.9); ctx.lineTo(0, sz*0.35);
      ctx.lineTo(-sz*0.3, sz*0.9); ctx.lineTo(-sz*0.6, sz*0.2);
      ctx.quadraticCurveTo(-sz*0.62, -sz*0.5, 0, -sz);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#fff';                                        // hai đốm mắt
      ctx.beginPath(); ctx.arc(-sz*0.2, -sz*0.24, sz*0.13, 0, 7); ctx.fill();
      ctx.beginPath(); ctx.arc(sz*0.2, -sz*0.24, sz*0.13, 0, 7); ctx.fill();
      ctx.restore();
    }
    arc(X, Y, R*(0.35 + k*0.6), 0, 7, C2, 2.5, a*0.45);

  } else if (S === 'groundburst'){ // Rageful Blow — giáng vũ khí xuống, nền toác ra thành tia
    const kk = Math.min(1, k*1.6);
    disc(X, Y, R*0.3*(1 - kk*0.5), '#fff', a*(1-kk)*0.8);            // lóe trắng ở điểm va chạm
    for (let i = 0; i < 9; i++){                                     // vết nứt toả ra, dài dần
      const aa = i*0.698 + spin;
      const L = R*(0.2 + kk*0.95) * (i % 2 ? 1 : 0.72);
      ctx.strokeStyle = i % 2 ? C1 : C2; ctx.lineWidth = 5.5*(1 - kk*0.6); ctx.globalAlpha = a*0.9;
      ctx.beginPath(); ctx.moveTo(X, Y);
      ctx.lineTo(X + Math.cos(aa + 0.12)*L*0.55, Y + Math.sin(aa + 0.12)*L*0.55);
      ctx.lineTo(X + Math.cos(aa)*L, Y + Math.sin(aa)*L); ctx.stroke();
    }
    arc(X, Y, R*(0.15 + kk*0.9), 0, 7, C2, 4*(1-kk) + 1, a*0.7);
    for (let i = 0; i < 5; i++){ const aa = i*1.257 + 0.4;           // mảnh đất bắn lên
      const L = R*(0.3 + kk*0.7);
      ctx.save(); ctx.translate(X + Math.cos(aa)*L, Y + Math.sin(aa)*L - kk*22); ctx.rotate(aa + k*6);
      ctx.fillStyle = C1; ctx.globalAlpha = a*(1-kk);
      ctx.fillRect(-4, -3, 8, 6); ctx.restore(); }

  } else if (S === 'lightwave'){ // Power Slash — sóng ánh sáng rời khỏi lưỡi kiếm và bay đi
    // MU tả chiêu này là "vung kiếm phóng ra một luồng sóng", nên sóng phải RỜI KHỎI người và
    // tiến ra xa, khác hẳn crescents (mấy vành trăng đứng yên tại chỗ chém).
    const push = R*k*0.55;                                            // tâm sóng trôi ra trước
    const cx = X + Math.cos(F)*push, cy = Y + Math.sin(F)*push;
    for (let i = 0; i < 3; i++){
      const rr = R*(0.55 + k*0.5) - i*R*0.16;
      if (rr <= 2) continue;
      arc(cx, cy, rr, F - 1.05, F + 1.05, i ? C2 : C1, (7 - i*2)*(1 - k*0.4), a*(0.95 - i*0.28));
    }
    arc(cx, cy, R*(0.55 + k*0.5), F - 1.05, F + 1.05, '#ffffff', 2, a*0.9);
    for (const sy of [-1, 1]){                                       // hai đầu sóng vuốt nhọn
      const ea = F + sy*1.05, rr = R*(0.55 + k*0.5);
      ctx.fillStyle = C1; ctx.globalAlpha = a*0.7; ctx.beginPath();
      ctx.moveTo(cx + Math.cos(ea)*rr, cy + Math.sin(ea)*rr);
      ctx.lineTo(cx + Math.cos(ea + sy*0.3)*rr*0.78, cy + Math.sin(ea + sy*0.3)*rr*0.78);
      ctx.lineTo(cx + Math.cos(ea - sy*0.12)*rr*0.86, cy + Math.sin(ea - sy*0.12)*rr*0.86);
      ctx.closePath(); ctx.fill();
    }

  } else if (S === 'firelines'){ // Fire Scream — BA vệt lửa quét xuống đất rồi mới bung nổ
    // Đúng mô tả gốc của chiêu trong MU. Style demonburst cũ bung tám tia đều nhau ngay từ khung
    // đầu — nhìn giống mọi chiêu diện rộng khác, không có nhịp "quét trước, nổ sau".
    const quet = Math.min(1, k*2.2);                                  // pha 1: ba vệt lửa chạy ra
    const no   = Math.max(0, (k - 0.45) / 0.55);                      // pha 2: vụ nổ ở cuối vệt
    for (const off of [-0.42, 0, 0.42]){
      const aa = F + off, L = R*0.95*quet;
      // C1 là màu LỚP (Dark Lord ô-liu), C2 mới là màu chiêu (cam lửa). Bản đầu để C1 làm lõi nên
      // ngọn lửa ra màu rêu. Nay lớp: quầng ngoài màu lớp — thân lửa C2 — lõi trắng nóng.
      ctx.strokeStyle = C1; ctx.lineWidth = 15*(1 - k*0.35); ctx.globalAlpha = a*0.32;
      ctx.beginPath(); ctx.moveTo(X, Y); ctx.lineTo(X + Math.cos(aa)*L, Y + Math.sin(aa)*L); ctx.stroke();
      ctx.strokeStyle = C2; ctx.lineWidth = 9*(1 - k*0.35); ctx.globalAlpha = a*0.9; ctx.stroke();
      ctx.strokeStyle = '#fff6d0'; ctx.lineWidth = 3.2*(1 - k*0.35); ctx.globalAlpha = a; ctx.stroke();
      for (let i = 1; i <= 3; i++){                                   // lưỡi lửa liếm dọc vệt
        const t = i/3.4, px = X + Math.cos(aa)*L*t, py = Y + Math.sin(aa)*L*t;
        disc(px, py, (6 - i)*(1 - k*0.4), i % 2 ? '#fff6d0' : C2, a*0.8);
      }
      if (no > 0){                                                    // vụ nổ ở cuối vệt
        const ex = X + Math.cos(aa)*R*0.95, ey = Y + Math.sin(aa)*R*0.95;
        disc(ex, ey, R*0.4*no, C1, a*(1 - no)*0.4);
        disc(ex, ey, R*0.28*no, C2, a*(1 - no)*0.9);
        disc(ex, ey, R*0.14*no, '#fff6d0', a*(1 - no));
        arc(ex, ey, R*0.4*no, 0, 7, C2, 3*(1-no) + 1, a*(1 - no)*0.9);
      }
    }
    disc(X, Y, R*0.2*(1 - k*0.5), '#fff6d0', a*0.7);

  } else if (S === 'spiritdragon'){ // Evil Spirit — hai con rồng bóng tối cuộn quanh rồi lao ra
    // Bản trước (spiritswarm) là bảy bóng ma lượn vòng — đúng nghĩa đen cái tên, nhưng trong MU
    // chiêu này bung ra hai con RỒNG quấn quanh người niệm rồi phóng đi. Chia làm hai nhịp:
    // nửa đầu cuộn siết vào, nửa sau duỗi thẳng lao ra ngoài.
    const siet = Math.min(1, k*2);                 // nhịp 1: cuộn vào
    const lao  = Math.max(0, (k - 0.5)*2);         // nhịp 2: lao ra
    disc(X, Y, R*(0.3 + siet*0.35), '#0c1408', a*0.34*(1 - lao*0.6));
    for (let d = 0; d < 2; d++){
      const goc = d*Math.PI + spin + siet*3.2 + lao*2.4;
      const ban = R*(0.72 - siet*0.3 + lao*0.95);  // siết vào rồi bung ra xa
      const cuon = 2.5 - lao*1.9;                  // đang cuộn thì thân xoắn, lao ra thì duỗi thẳng
      _vxDragon(X, Y, goc, ban, cuon, 18, R*0.095 + 3, d ? C2 : C1, d ? C1 : C2, a*0.95);
    }
    for (let i = 0; i < 6; i++){                   // khói âm bốc lên từ chỗ đứng
      const t = ((k*1.4 + i*0.17) % 1);
      disc(X + Math.sin(i*2.7 + k*5)*R*0.4, Y - t*R*0.55, (3.4 - t*2)*1.2, i%2 ? C2 : C1, a*(1-t)*0.55);
    }
    arc(X, Y, R*(0.35 + k*0.55), 0, 7, C2, 2, a*0.3);

  } else if (S === 'firepillar'){ // Fire Scream — ba vệt lửa chạy ra, tới cuối thì DỰNG CỘT LỬA
    // Mô tả gốc trong MU: "phun ba vệt lửa xuống đất, các vệt lửa sau đó nổ tung". Bản trước vẽ
    // đúng ba vệt nhưng cái "nổ" chỉ là một quầng sáng bẹt dưới đất — nhìn ra vũng nước hơn là lửa.
    // Nay cuối mỗi vệt mọc lên một CỘT lửa thật, cao dần rồi lay động.
    const chay = Math.min(1, k*2.4);               // nhịp 1: vệt lửa chạy ra
    const moc  = Math.max(0, (k - 0.34)/0.34);     // nhịp 2: cột lửa mọc lên
    for (let i = 0; i < 3; i++){
      const aa = F + (i-1)*0.46, L = R*0.95;
      const tx = X + Math.cos(aa)*L, ty = Y + Math.sin(aa)*L;
      ctx.strokeStyle = C1; ctx.lineWidth = 13*(1 - k*0.4); ctx.globalAlpha = a*0.3;
      ctx.beginPath(); ctx.moveTo(X, Y);
      ctx.lineTo(X + Math.cos(aa)*L*chay, Y + Math.sin(aa)*L*chay); ctx.stroke();
      ctx.strokeStyle = C2; ctx.lineWidth = 6*(1 - k*0.4); ctx.globalAlpha = a*0.85; ctx.stroke();
      if (moc > 0)
        _vxFlameCol(tx, ty, R*1.05, R*0.22, moc*1.5, k*9 + i*2.2, C1, C2, a);
    }
    disc(X, Y, R*0.18*(1 - k*0.4), '#fff6d0', a*0.7);

  } else if (S === 'flamewall'){ // Flame Strike — một HÀNG cột lửa dựng lên phía trước
    // MU tả: "vung vũ khí về hướng chỉ định, gây sát thương lửa lên nhiều mục tiêu". Nên đây là
    // một bức tường lửa quét về phía trước, không phải vòng xoáy tại chỗ (style vortex cũ).
    for (let i = 0; i < 5; i++){
      const lech = (i - 2) * 0.30;
      const aa = F + lech, L = R*(0.5 + Math.abs(lech)*0.32);
      const px = X + Math.cos(aa)*L, py = Y + Math.sin(aa)*L;
      const tre = i === 2 ? 0 : Math.abs(i - 2)*0.11;        // giữa mọc trước, hai bên theo sau
      const kk = (k - tre) / (0.42 - tre*0.2);
      if (kk <= 0) continue;
      _vxFlameCol(px, py, R*(1.1 - Math.abs(lech)*0.55), R*0.2, kk, k*8 + i*1.9, C1, C2, a);
    }
    ctx.strokeStyle = C2; ctx.lineWidth = 4; ctx.globalAlpha = a*0.5;  // vệt quét dưới chân tường
    ctx.beginPath(); ctx.arc(X, Y, R*0.6, F - 0.78, F + 0.78); ctx.stroke();
    ctx.globalAlpha = 1;

  } else if (S === 'boltdown'){ // Lightning / Electric Spark — sét giáng TỪ TRÊN TRỜI xuống
    // Style flash cũ chỉ loè một vòng cung quanh người niệm, không ai đọc ra đó là sét. Sét thì
    // phải đến từ trên cao và đánh xuống một điểm — nhịp đó mới nói được "sét".
    const roi = Math.min(1, k*3.2);                 // tia sét lao xuống rất nhanh
    const no  = Math.max(0, (k - 0.3)/0.7);
    for (let i = 0; i < 3; i++){
      const px = X + Math.cos(F)*R*(0.4 + i*0.28), py = Y + Math.sin(F)*R*(0.4 + i*0.28)*0.7;
      const cao = R*1.5;
      if (roi > 0.02){
        ctx.globalAlpha = a*(1 - no*0.75);
        _vxBolt(px, py - cao, Math.PI/2, cao*roi, R*0.13, i % 2 ? C2 : C1);
      }
      if (no > 0){
        disc(px, py, R*0.3*no, C2, a*(1 - no)*0.8);
        arc(px, py, R*0.34*no, 0, 7, C1, 3*(1-no) + 1, a*(1 - no));
        for (let j = 0; j < 4; j++){                 // tia con nảy ra khỏi điểm chạm
          const aj = j*1.57 + i;
          ctx.globalAlpha = a*(1 - no)*0.7; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.8;
          _vxLine(px, py, px + Math.cos(aj)*R*0.4*no, py + Math.sin(aj)*R*0.26*no);
        }
      }
    }
    ctx.globalAlpha = 1;

  } else if (S === 'stabburst'){ // Death Stab — chuỗi nhát đâm liên tiếp, không phải một cú
    // Tên chiêu trong MU ghi rõ "gây HAI nấc sát thương". Một vòng cung tĩnh không nói được điều
    // đó; ba nhát đâm nối nhau theo thời gian thì nói được.
    for (let i = 0; i < 3; i++){
      const kk = (k - i*0.16) / 0.34;
      if (kk <= 0 || kk >= 1) continue;
      const L = R*(0.25 + kk*0.85), lech = (i - 1)*0.17;
      const aa = F + lech;
      const tx = X + Math.cos(aa)*L, ty = Y + Math.sin(aa)*L*0.8;
      ctx.globalAlpha = a*(1 - kk)*0.95;
      ctx.strokeStyle = i === 1 ? C1 : C2; ctx.lineWidth = 7 - i*1.6; ctx.lineCap = 'round';
      _vxLine(X + Math.cos(aa)*R*0.2, Y + Math.sin(aa)*R*0.16, tx, ty);
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 2.2; _vxLine(X + Math.cos(aa)*R*0.3, Y + Math.sin(aa)*R*0.24, tx, ty);
      ctx.fillStyle = '#fff';                        // chớp sáng ở mũi nhát đâm
      ctx.beginPath(); ctx.moveTo(tx + Math.cos(aa)*10, ty + Math.sin(aa)*10);
      ctx.lineTo(tx + Math.cos(aa + 2.1)*9, ty + Math.sin(aa + 2.1)*9);
      ctx.lineTo(tx + Math.cos(aa - 2.1)*9, ty + Math.sin(aa - 2.1)*9);
      ctx.closePath(); ctx.fill();
    }
    ctx.globalAlpha = 1;

  } else if (S === 'novaburst'){ // Nova — DỒN năng lượng vào tâm rồi mới bung ra
    // "Chiêu mạnh nhất trong game" mà bung ra ngay khung đầu thì không khác gì mọi chiêu diện
    // rộng khác. Sức nặng nằm ở nhịp dồn: nửa giây các vòng siết vào trước khi nổ.
    const don = Math.min(1, k/0.45), no = Math.max(0, (k - 0.45)/0.55);
    if (no <= 0){
      for (let i = 0; i < 5; i++){                   // các vòng siết vào tâm
        const t = ((don + i*0.2) % 1);
        arc(X, Y, R*(1.05 - t*0.85), 0, 7, i % 2 ? C1 : C2, 3.4, a*t*0.85);
      }
      disc(X, Y, R*0.1 + don*R*0.16, '#fff', a*don);
    } else {
      disc(X, Y, R*0.42*(1 - no), '#fff', a*(1 - no));
      for (let i = 0; i < 3; i++){                   // ba lớp sóng nổ nối nhau
        const t = Math.max(0, no - i*0.14);
        if (t <= 0) continue;
        arc(X, Y, R*t*1.15, 0, 7, i ? C2 : C1, (9 - i*2.5)*(1 - t), a*(1 - t)*0.95);
      }
      for (let i = 0; i < 12; i++){                  // tia bắn ra tứ phía
        const aa = i*0.5236;
        ctx.globalAlpha = a*(1 - no)*0.8; ctx.strokeStyle = i % 2 ? C1 : '#fff'; ctx.lineWidth = 3;
        _vxLine(X + Math.cos(aa)*R*no*0.5, Y + Math.sin(aa)*R*no*0.5*0.8,
                X + Math.cos(aa)*R*no*1.1, Y + Math.sin(aa)*R*no*1.1*0.8);
      }
    }
    ctx.globalAlpha = 1;

  } else if (S === 'icefall'){ // Ice — phiến băng KẾT TRÊN CAO rồi rơi xuống vỡ tan
    for (let i = 0; i < 7; i++){
      const seed = i*2.39;
      const px = X + Math.cos(seed)*R*0.72, gy = Y + Math.sin(seed)*R*0.42;
      const kk = (k - i*0.055) / 0.5;
      if (kk <= 0) continue;
      if (kk < 1){                                   // phiến băng đang rơi
        const py = gy - R*0.95*(1 - kk);
        ctx.save(); ctx.translate(px, py); ctx.rotate(seed + kk*2);
        ctx.globalAlpha = a*0.95; ctx.fillStyle = i % 2 ? C1 : C2;
        ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(5, 3); ctx.lineTo(0, 10); ctx.lineTo(-5, 3);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#fff'; ctx.globalAlpha = a*0.8;
        ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(2, 2); ctx.lineTo(0, 7); ctx.closePath(); ctx.fill();
        ctx.restore();
      } else {                                       // đã chạm đất, vỡ thành hoa băng
        const v = Math.min(1, (kk - 1)*2.6);
        _vxFlake(px, gy, 5 + v*11, C2, a*(1 - v)*0.9);
        arc(px, gy, 4 + v*15, 0, 7, C1, 2, a*(1 - v)*0.7);
      }
    }
    ctx.globalAlpha = 1;

  } else if (S === 'poisonbloom'){ // Poison — vũng độc LOANG RA rồi sủi bọt
    const loang = Math.min(1, k*1.8);
    ctx.globalAlpha = a*0.3; ctx.fillStyle = C1;
    ctx.beginPath(); ctx.ellipse(X, Y, R*0.85*loang, R*0.5*loang, 0, 0, 7); ctx.fill();
    arc(X, Y, R*0.85*loang, 0, 7, C2, 2.5, a*0.6);
    for (let i = 0; i < 9; i++){                     // bọt độc nổi lên rồi vỡ
      const t = ((k*1.6 + i*0.111) % 1);
      const seed = i*1.87;
      const px = X + Math.cos(seed)*R*0.62*loang, py = Y + Math.sin(seed)*R*0.36*loang;
      disc(px, py - t*R*0.4, (4.5 - t*3)*1.1, i % 3 ? C2 : '#ffffff', a*(1 - t)*0.85);
    }
    ctx.globalAlpha = 1;

  } else if (S === 'quakeburst'){ // Earthquake (Dark Lord) — nền đất nứt theo vòng, đá vụn bật lên
    // Ba nhịp trong một hoạt ảnh: (1) giậm — vòng bụi NÉN vào tâm, (2) nứt — đường gãy khúc chạy
    // ra, (3) bật — đá vụn nảy lên rồi rơi. Khác hẳn 'groundburst' của Rageful Blow (một cú giáng,
    // tia thẳng, không có nhịp nén) — hai chiêu cùng kiểu "đập xuống đất" mà nhìn không lẫn nhau.
    const nen = Math.min(1, k / 0.22), no = Math.max(0, (k - 0.22) / 0.78);
    if (nen < 1) arc(X, Y, R*(1.15 - nen*0.5), 0, 7, C2, 4, a*0.5*(1 - nen));
    if (no > 0){
      const rr = R*(0.25 + no*0.95);
      for (let i = 0; i < 3; i++){                       // ba vòng nứt lệch pha
        const f = no - i*0.13; if (f <= 0) continue;
        arc(X, Y, R*(0.2 + f*0.95), 0, 7, i ? C2 : C1, 5 - i*1.4, a*0.55*(1 - f));
      }
      ctx.strokeStyle = C1; ctx.lineWidth = 3.2; ctx.globalAlpha = a*0.85*(1 - no);
      for (let i = 0; i < 9; i++){                       // đường nứt gãy khúc
        const a0 = i/9*Math.PI*2 + spin, a1 = a0 + (i%2 ? 0.16 : -0.16);
        ctx.beginPath();
        ctx.moveTo(X + Math.cos(a0)*R*0.12, Y + Math.sin(a0)*R*0.12);
        ctx.lineTo(X + Math.cos(a0)*rr*0.55, Y + Math.sin(a0)*rr*0.55);
        ctx.lineTo(X + Math.cos(a1)*rr, Y + Math.sin(a1)*rr);
        ctx.stroke();
      }
      ctx.fillStyle = C2;                                // đá vụn bật lên rồi rơi
      for (let i = 0; i < 12; i++){
        const aa = i/12*Math.PI*2 + spin*1.7, d = rr*(0.35 + (i%4)*0.18);
        const up = Math.sin(Math.min(1, no*1.6)*Math.PI) * 26 * (1 - (i%3)*0.22);
        ctx.globalAlpha = a*0.8*(1 - no);
        ctx.fillRect(X + Math.cos(aa)*d - 3, Y + Math.sin(aa)*d*0.72 - up - 3, 6, 6);
      }
      ctx.globalAlpha = 1;
    }
    _vxGlyph(X, Y, G, 24, C2, a*0.8);
  } else if (S === 'crowswarm'){ // Dark Raven (Dark Lord) — bầy quạ đen xoáy vào, cánh nhọn xé gió
    disc(X, Y, R*(0.5 + k*0.2), '#0a0612', a*0.35);
    for (let i = 0; i < 8; i++){
      const aa = i*0.7854 + spin + k*5;
      const rr = R*(0.85 - k*0.55);
      const cx = X + Math.cos(aa)*rr, cy = Y + Math.sin(aa)*rr*0.7;
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(aa + Math.PI/2); ctx.globalAlpha = a*0.85;
      ctx.fillStyle = i%2 ? C1 : '#140a1e';
      ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(-9,-4); ctx.lineTo(-2,0); ctx.lineTo(-9,4); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(9,-4); ctx.lineTo(2,0); ctx.lineTo(9,4); ctx.closePath(); ctx.fill();
      ctx.restore();
      if (i%3 === 0) disc(cx, cy, 1.8, C2, a);
    }
    _vxGlyph(X, Y, G, 26, C2, a*0.9);
  }
  ctx.restore();
}
function drawProjStyled(p){
  const s = p.style || 'dart', dx = Math.cos(p.ang), dy = Math.sin(p.ang);
  ctx.save(); ctx.lineCap = 'round';
  if (s === 'beam' || s === 'beam2'){ // chỉ lực / kiếm khí xuyên thấu
    const w = s === 'beam2' ? 8 : 5, L = s === 'beam2' ? 34 : 26;
    ctx.strokeStyle = p.color; ctx.lineWidth = w; ctx.globalAlpha = 0.9;
    ctx.beginPath(); ctx.moveTo(p.x - dx*L, p.y - dy*L); ctx.lineTo(p.x, p.y); ctx.stroke();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = s === 'beam2' ? 3 : 2;
    ctx.beginPath(); ctx.moveTo(p.x - dx*L*0.7, p.y - dy*L*0.7); ctx.lineTo(p.x, p.y); ctx.stroke();
  } else if (s === 'blade'){ // đao quang trăng lưỡi liềm
    ctx.strokeStyle = p.color; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(p.x - dx*10, p.y - dy*10, 14, p.ang - 1.2, p.ang + 1.2); ctx.stroke();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(p.x - dx*10, p.y - dy*10, 10, p.ang - 1, p.ang + 1); ctx.stroke();
  } else if (s === 'shard'){ // mảnh băng/chỉ khí
    ctx.fillStyle = p.color; ctx.beginPath();
    ctx.moveTo(p.x + dx*10, p.y + dy*10); ctx.lineTo(p.x - dx*8 - dy*5, p.y - dy*8 + dx*5); ctx.lineTo(p.x - dx*8 + dy*5, p.y - dy*8 - dx*5); ctx.closePath(); ctx.fill();
  } else if (s === 'serpent'){ // kim xà uốn lượn
    ctx.strokeStyle = p.color; ctx.lineWidth = 3.5; ctx.beginPath();
    for (let i = 0; i <= 6; i++){ const t = i/6; const off = Math.sin(t*6 + (p.seed || 0))*7;
      const px = p.x - dx*26*t - dy*off, py = p.y - dy*26*t + dx*off; i ? ctx.lineTo(px, py) : ctx.moveTo(px, py); } ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(p.x, p.y, 3, 0, 7); ctx.fill();
  } else if (s === 'note'){ // âm ba sưu hồn — vòng sóng âm
    ctx.strokeStyle = p.color; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(p.x, p.y, 5 + ((p.seed || 0)%3), 0, 7); ctx.stroke();
    ctx.beginPath(); ctx.arc(p.x - dx*12, p.y - dy*12, 3.5, 0, 7); ctx.stroke();
  } else if (s === 'sword'){ // phi kiếm
    _vxSword(p.x, p.y, p.ang, 24, p.color, 0.95);
  } else if (s === 'orb'){ // quang cầu
    const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, 9);
    g.addColorStop(0, '#fff'); g.addColorStop(0.4, p.color); g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(p.x, p.y, 9, 0, 7); ctx.fill();
  } else if (s === 'arrow'){ // Multi-Shot (Sylvan Ranger) — thân tên + mũi nhọn + lông vũ đuôi
    ctx.strokeStyle = p.color; ctx.lineWidth = 2.2;
    ctx.beginPath(); ctx.moveTo(p.x - dx*18, p.y - dy*18); ctx.lineTo(p.x - dx*4, p.y - dy*4); ctx.stroke();
    ctx.fillStyle = p.color; ctx.beginPath();
    ctx.moveTo(p.x + dx*6, p.y + dy*6); ctx.lineTo(p.x - dx*2 - dy*3, p.y - dy*2 + dx*3); ctx.lineTo(p.x - dx*2 + dy*3, p.y - dy*2 - dx*3); ctx.closePath(); ctx.fill();
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(p.x - dx*18 - dy*3, p.y - dy*18 + dx*3); ctx.lineTo(p.x - dx*14, p.y - dy*14); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(p.x - dx*18 + dy*3, p.y - dy*18 - dx*3); ctx.lineTo(p.x - dx*14, p.y - dy*14); ctx.stroke();
  } else if (s === 'lance'){ // Penetration (Sylvan Ranger) — mũi tên xuyên, kéo theo vệt sáng dài
    // Mũi tên thường (style 'arrow') dừng ở con đầu tiên, nên nó vẽ ngắn và gọn. Chiêu này XUYÊN
    // cả hàng, nên hình phải nói được điều đó: một vệt sáng dài chạy suốt phía sau, không đứt.
    const gr = ctx.createLinearGradient(p.x - dx*46, p.y - dy*46, p.x, p.y);
    gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(0.55, p.color); gr.addColorStop(1, '#ffffff');
    ctx.strokeStyle = gr; ctx.lineWidth = 5; ctx.globalAlpha = 0.9;
    ctx.beginPath(); ctx.moveTo(p.x - dx*46, p.y - dy*46); ctx.lineTo(p.x - dx*3, p.y - dy*3); ctx.stroke();
    ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.8; ctx.globalAlpha = 1;
    ctx.beginPath(); ctx.moveTo(p.x - dx*34, p.y - dy*34); ctx.lineTo(p.x - dx*3, p.y - dy*3); ctx.stroke();
    ctx.fillStyle = p.color; ctx.beginPath();                        // đầu mũi dài và nhọn
    ctx.moveTo(p.x + dx*11, p.y + dy*11);
    ctx.lineTo(p.x - dx*5 - dy*5, p.y - dy*5 + dx*5);
    ctx.lineTo(p.x - dx*1, p.y - dy*1);
    ctx.lineTo(p.x - dx*5 + dy*5, p.y - dy*5 - dx*5); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.beginPath();
    ctx.moveTo(p.x + dx*9, p.y + dy*9);
    ctx.lineTo(p.x - dx*2 - dy*2, p.y - dy*2 + dx*2);
    ctx.lineTo(p.x - dx*2 + dy*2, p.y - dy*2 - dx*2); ctx.closePath(); ctx.fill();
  } else { // dart — kiểu cũ mặc định
    ctx.strokeStyle = p.color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(p.x - dx*16, p.y - dy*16); ctx.lineTo(p.x, p.y); ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(p.x, p.y, 3, 0, 7); ctx.fill();
  }
  ctx.restore();
}
function spawnSkillVfx(id, v, phase, ang, R, x0, y0){
  const c = VH_VFX[id] || SECT_VFX[id] || null;
  const col = v.color || '#7ecbff', c2 = (c && c.c2) || '#ffffff', glyph = v.glyph || '✦';
  const style = (c && c.style) || ({ cone:'crescents', cast:'flash', aoe:'suns', dash:'wuxing', buff:'vajra' })[phase] || 'flash';
  // Thời lượng mặc định 0,4-0,7 giây đủ cho một hình nở ra rồi tắt, nhưng KHÔNG đủ cho hoạt ảnh
  // có nhịp: cột lửa phải mọc lên rồi mới lay, rồng phải cuộn xong mới lao ra, Nova phải dồn
  // trước khi nổ. Chiêu nào có hoạt ảnh nhiều nhịp thì khai `dur` riêng trong bảng VFX.
  const _d = (t) => (c && c.dur) || t;
  if (phase === 'cone'){
    addEffect({ type:'vfx', style, x:player.x, y:player.y, face:ang, r:R, c1:col, c2, glyph, dur:_d(0.55), spin:(c && c.spin) || 0 });
    for (let i = 0; i < 5; i++) addEffect({ type:'ink', x:player.x + Math.cos(ang)*rnd(30,90), y:player.y + Math.sin(ang)*rnd(30,90), vx:rnd(-30,30), vy:rnd(-60,-10), color:c2 });
  } else if (phase === 'cast'){
    addEffect({ type:'vfx', style, x:player.x, y:player.y, face:ang, r:R, c1:col, c2, glyph, dur:_d(0.4) });
  } else if (phase === 'aoe'){
    addEffect({ type:'vfx', style, x:player.x, y:player.y, face:ang, r:R, c1:col, c2, glyph, dur:_d(0.7), big:true, spin:(c && c.spin) || 0 });
    addEffect({ type:'vfx', style:'shock', x:player.x, y:player.y, face:0, r:R, c1:col, c2, glyph, dur:0.5 });
  } else if (phase === 'dash'){
    addEffect({ type:'vfx', style, x:player.x, y:player.y, face:ang, r:R, c1:col, c2, glyph, dur:_d(0.6), x0, y0 });
    addEffect({ type:'vfx', style:'shock', x:player.x, y:player.y, face:0, r:80, c1:col, c2, glyph, dur:0.45 });
  } else if (phase === 'buff'){
    addEffect({ type:'vfx', style, x:player.x, y:player.y, face:0, r:R, c1:col, c2, glyph, dur:_d(1.0), big:true, spin:(c && c.spin) || 0 });
  }
}

function castVohoc(id){
  const v = VOHOC_DEFS[id] || FUSION_DEFS[id]; if (!v) return;
  const tierC = VH_TIER[v.tier].color, col = v.color || tierC;
  const fx = v.fx || {};
  const _st = evoStage(id); // bậc tiến hóa (Lv 40/80/120)
  const _ev = skEvoMult(id);   // nhánh đã chọn: Bá Đạo / Tốc Chiến / Lan Toả
  const _mul = (1 + (player.skillDmgPct || 0)) * _ev.dmg;
  addFloat(player.x, player.y-46, `«${v.name}»`, col, 14);
  const hitMob = (m, mult) => {
    let dmg = player.atk * mult * _mul * rnd(0.92, 1.08);
    if (fx.pierce) dmg *= 1.3; // xuyên giáp
    const crit = Math.random() < player.crit;
    if (crit) dmg *= (player.critDmgMult || 2);
    hurtMob(m, Math.round(dmg), crit ? 'crit' : 'tp');
    if (m.dead) return;
    // Sourced per-class action SFX (axie-origins-asset-kit) — flavors the VOHOC/FUSION hit landing by
    // archetype: bleed reads as a claw/bite chomp, aoe reads as a heavier gore-style hit, kb (no bleed)
    // reads as a knockback/throw. Additive layer alongside the fx floats/status below, not a replacement.
    const _hitCls = SECT_SFX[player.sect];
    if (_hitCls){
      if (fx.bleed) AudioSys.sfx('bite_' + _hitCls, 0.45);
      else if (v.type === 'aoe') AudioSys.sfx('gore_' + _hitCls, 0.45);
      else if (fx.kb) AudioSys.sfx('throw_' + _hitCls, 0.45);
    }
    if (fx.stun){ m.stunT = Math.max(m.stunT || 0, fx.stun * (m.def.bossKind ? 0.4 : 1)); addFloat(m.x, m.y-m.def.size-24, 'CHOÁNG!', '#ffe9a8', 11); playStatusFx('stunned', 'stunned', m.x, m.y, 0.5, 0.3); }
    if (fx.slow){ m.slowT = Math.max(m.slowT || 0, fx.slow.t); m.slowPct = 1 - fx.slow.pct; addFloat(m.x, m.y-m.def.size-24, 'CHẬM!', '#7ab0d8', 11); playStatusFx('weak', 'weak', m.x, m.y, 0.45, 0.28); }
    if (fx.bleed){ m.bleedT = fx.bleed.t; m.bleedDps = Math.max(1, Math.round(player.atk * 0.35)); addFloat(m.x, m.y-m.def.size-24, 'CHẢY MÁU!', '#c03a4a', 11); playStatusFx('bleed', 'bleed_apply', m.x, m.y, 0.5, 0.3); }
    if (fx.kb) vhKnockback(m, Math.atan2(m.y - player.y, m.x - player.x), fx.kb);
  };
  if (v.type === 'cone'){
    const t = nearestMob(220);
    if (t) player.face = Math.atan2(t.y - player.y, t.x - player.x);
    const R = 135 * _ev.r;
    spawnSkillVfx(id, v, 'cone', player.face, R);
    aoeHit(() => {
      for (const m of mobs){
        if (m.dead) continue;
        if (dist(player.x, player.y, m.x, m.y) >= R + m.def.size) continue;
        let da = Math.atan2(m.y - player.y, m.x - player.x) - player.face;
        while (da > Math.PI) da -= 2*Math.PI; while (da < -Math.PI) da += 2*Math.PI;
        if (Math.abs(da) < 1.05) hitMob(m, v.mult);
      }
    });
    if (fx.selfEva){ player.vhEvaT = fx.selfEva.t; player.vhEvaPct = fx.selfEva.pct; addFloat(player.x, player.y-60, `+${fx.selfEva.pct}% né (${fx.selfEva.t}s)`, '#a0ffe9', 12); }
    for (let _w = 1; _w <= _st; _w++){ // tiến hóa: sóng chưởng nối tiếp, mỗi sóng rộng hơn
      const _wm = _w === 1 ? 0.55 : 0.4, _Rw = R * (1 + 0.18 * _w), _fw = player.face, _px = player.x, _py = player.y;
      setTimeout(() => {
        if (!player || dead) return;
        addEffect({ type:'cone', x:_px, y:_py, face:_fw, r:_Rw, color:col });
        aoeHit(() => {
          for (const m of mobs){
            if (m.dead) continue;
            if (dist(_px, _py, m.x, m.y) >= _Rw + m.def.size) continue;
            let da = Math.atan2(m.y - _py, m.x - _px) - _fw;
            while (da > Math.PI) da -= 2*Math.PI; while (da < -Math.PI) da += 2*Math.PI;
            if (Math.abs(da) < 1.05) hitMob(m, v.mult * _wm);
          }
        });
      }, _w * 240);
    }
  }
  else if (v.type === 'proj'){
    const t = nearestMob(560);
    const base = t ? Math.atan2(t.y - player.y, t.x - player.x) : player.face;
    player.face = base;
    const n = (fx.multi || 1) + _st, spd = fx.speed || 540; // tiến hóa: +1 đạo mỗi bậc (Lục Mạch 1→2→3→4 kiếm)
    const _vc = VH_VFX[id] || null;
    for (let i = 0; i < n; i++){
      const off = n > 1 ? (i - (n-1)/2) * 0.18 : 0;
      projectiles.push({ x:player.x, y:player.y, ang:base + off, speed:spd, dmg:player.atk * v.mult * _mul, kind:'skill', life:0.95, color:(_vc && _vc.rainbow) ? `hsl(${Math.round(i*360/Math.max(n,1))},85%,66%)` : col, pierce:!!fx.pierce, vhfx:fx, style:(_vc && _vc.proj) || undefined, seed:i });
    }
    spawnSkillVfx(id, v, 'cast', base, 56);
    // Sourced per-class projectile-launch SFX — VOHOC/FUSION 'proj' skills only ever got the
    // generic 'skill' sfx (set at the bottom of castSkill) before this; this is additive, not a swap.
    const _projCls = SECT_SFX[player.sect];
    if (_projCls) AudioSys.sfx('projatk_' + _projCls, 0.45);
  }
  else if (v.type === 'aoe'){
    const R = (fx.r || 160) * (1 + 0.12 * _st) * _ev.r; // tiến hóa: phạm vi +12%/bậc · Lan Toả nhân thêm
    spawnSkillVfx(id, v, 'aoe', player.face, R);
    shakeT = Math.max(shakeT, 0.2); shakeMag = Math.max(shakeMag, fx.big ? 7 : 4);
    aoeHit(() => {
      for (const m of mobs){
        if (m.dead) continue;
        if (dist(player.x, player.y, m.x, m.y) < R + m.def.size) hitMob(m, v.mult);
      }
    });
    for (let _w = 1; _w <= _st; _w++){ // tiến hóa: dư chấn nổ tiếp thành từng vòng
      const _wm = _w === 1 ? 0.5 : 0.35, _Rw = R * (1 + 0.15 * _w), _px = player.x, _py = player.y;
      setTimeout(() => {
        if (!player || dead) return;
        addEffect({ type:'ring', x:_px, y:_py, r:_Rw, color:col, big:true });
        aoeHit(() => { for (const m of mobs){ if (m.dead) continue; if (dist(_px, _py, m.x, m.y) < _Rw + m.def.size) hitMob(m, v.mult * _wm); } });
      }, _w * 260);
    }
  }
  // (nhánh type:'dash' đã xoá — không còn chiêu nào mang type đó sau đợt MU-hoá)
  else if (v.type === 'buff'){
    spawnSkillVfx(id, v, 'buff', 0, 95);
    const _bt = Math.round((fx.t || 0) * (1 + 0.5 * _st)); // tiến hóa: buff bền +50%/bậc
    if (fx.dmgPct){ player.vhDmgT = _bt; player.vhDmgPct = fx.dmgPct; addFloat(player.x, player.y-60, `+${fx.dmgPct}% Sát Thương (${_bt}s)`, col, 13); }
    if (fx.shieldPct){ player.vhShield = Math.round(player.maxHp * fx.shieldPct * (1 + 0.25 * _st) / 100); addFloat(player.x, player.y-60, `🛡 KHIÊN ${player.vhShield}`, '#8ad8c8', 13); playStatusFx('shield', 'shield', player.x, player.y, 0.55, 0.32); }
    // Bless (Sylvan Ranger) — lớp hỗ trợ là lớp DUY NHẤT hồi máu bằng chiêu; bốn lớp kia có
    // khiên / giảm sát thương / tốc đánh / bạo kích, không lớp nào trùng cơ chế lớp nào.
    if (fx.healPct){
      const _h = Math.round(player.maxHp * fx.healPct * (1 + 0.25 * _st) / 100);
      player.hp = Math.min(player.maxHp, player.hp + _h);
      addFloat(player.x, player.y-74, `✚ +${_h} Sinh Lực`, '#8fd18f', 13);
    }
    if (fx.reflect){ player.vhReflT = _bt; addFloat(player.x, player.y-60, `PHẢN ĐÒN ${_bt}s!`, col, 13); }
    if (fx.aspdPct){ player.vhAspdT = _bt; player.vhAspdPct = fx.aspdPct; addFloat(player.x, player.y-60, `TỐC ĐÁNH +${fx.aspdPct}%`, col, 13); }
    if (fx.crit){ player.vhCritT = _bt; addFloat(player.x, player.y-74, `BẠO KÍCH ${_bt}s!`, '#ff6a5a', 13); }
    if (fx.leechPct){ player.vhLeechT = _bt; addFloat(player.x, player.y-60, `HÚT SINH LỰC ${_bt}s`, col, 13); }
    if (fx.resetCd){ for (const k in player.cd) player.cd[k] = 0; player.cd[id] = v.cd * skCdScale(id); addFloat(player.x, player.y-74, 'VÔ TƯỚNG — toàn bộ chiêu đã hồi!', '#b8e8ff', 13); }
    calcDerived();
  }
}

// ============================================================
// LỊCH THẾ GIỚI — đồng hồ trong game: mùa + canh giờ, ảnh hưởng spawn và sự kiện
// 12 canh/ngày · 30 ngày/tháng · 3 tháng/mùa · 4 mùa/năm
// 1 ngày game = 10 phút thật → 1 tháng ≈ 5 giờ, 1 năm ≈ 20 giờ chơi
// ============================================================
// (tên 12 canh Địa Chi đã gỡ — frac trong gameTimeInfo() vẫn là nguồn nhịp ngày/đêm)
const GT_DAY = 600; // giây thật cho 1 ngày game
const SEASONS = [
  { id:'xuan', name:'Xuân', icon:'🌸', color:'#f0a8c0', buffTxt:'+5% EXP',         amb:{ kind:'petal', color:'#f5b8cc', n:26 }, dawn:0.25, dusk:0.75 },
  { id:'ha',   name:'Hạ',   icon:'☀',  color:'#ffd76a', buffTxt:'+5% hồi Mana', amb:{ kind:'rain',  color:'#9ec8e8', n:34 }, dawn:0.23, dusk:0.77 },
  { id:'thu',  name:'Thu',  icon:'🍂', color:'#e8944a', buffTxt:'+8% Lumen rơi',      amb:{ kind:'leaf',  color:'#d87a3a', n:26 }, dawn:0.25, dusk:0.75 },
  { id:'dong', name:'Đông', icon:'❄',  color:'#bfe0f0', buffTxt:'+5% phòng thủ',    amb:{ kind:'snow',  color:'#eef4ff', n:32 }, dawn:0.27, dusk:0.73 },
];
function gameClock(){ if (!player.gt) player.gt = { t: GT_DAY*0.30 }; return player.gt; }
let _gtiCache = null; // per-frame memo: player.gt.t only changes inside update(), never during render()
function gameTimeInfo(){
  if (_gtiCache) return _gtiCache;
  const gt = gameClock();
  const totalDays = Math.floor(gt.t / GT_DAY);
  const year  = Math.floor(totalDays / 360) + 1;
  const doy   = totalDays % 360;
  const month = Math.floor(doy / 30) + 1;
  const day   = doy % 30 + 1;
  const frac  = (gt.t % GT_DAY) / GT_DAY;       // 0 = 0h, 0.5 = 12h
  const canh  = Math.floor(frac * 12) % 12;      // 12 canh giờ
  const season = SEASONS[Math.floor((month - 1) / 3)] || SEASONS[0];
  return (_gtiCache = { year, month, day, canh, frac, season });
}
function isNightGame(){
  const i = gameTimeInfo();
  return i.frac < i.season.dawn - 0.02 || i.frac > i.season.dusk + 0.02;
}
function skyDarkness(){ // 0 = trưa sáng, 1 = đêm khuya — mùa quyết định ngày dài/ngắn
  const i = gameTimeInfo(), f = i.frac, w = 0.06;
  const dawn = i.season.dawn, dusk = i.season.dusk;
  if (f >= dawn && f <= dusk) return 0;
  if (f > dusk && f < dusk + w) return (f - dusk)/w;
  if (f < dawn && f > dawn - w) return (dawn - f)/w;
  return 1;
}

// ---------- Thoi tiet dong theo Lich Tu Tien (Goi B) — roll theo NGAY, deterministic ----------
const WX_TABLE = {
  xuan:[['sun',0.55],['drizzle',0.30],['fog',0.15]],
  ha:  [['sun',0.45],['storm',0.35],['sunhot',0.20]],
  thu: [['sun',0.55],['fog',0.30],['drizzle',0.15]],
  dong:[['sun',0.40],['snow',0.42],['fog',0.18]],
};
const WX_INFO = {
  sun:{icon:'☀', name:'Nắng đẹp'}, sunhot:{icon:'🌞', name:'Nắng gắt'},
  drizzle:{icon:'🌦', name:'Mưa phùn'}, storm:{icon:'⛈', name:'Mưa rào giông'},
  fog:{icon:'🌫', name:'Sương mù'}, snow:{icon:'❄', name:'Tuyết rơi'},
};
function weatherNow(){
  if (typeof player === 'undefined' || !player || !player.gt) return null;
  if (!curMap || curMap.startsWith('pb_')) return null; // phó bản không có thời tiết
  const g = gameTimeInfo();
  const h = Math.abs(Math.sin((g.year*4096 + g.month*97 + g.day*13 + 7) * 12.9898) * 43758.5453) % 1;
  const tbl = WX_TABLE[g.season.id] || WX_TABLE.xuan;
  let acc = 0, pick = 'sun';
  for (const [id, w] of tbl){ acc += w; if (h <= acc){ pick = id; break; } }
  return Object.assign({ id: pick }, WX_INFO[pick]);
}
let wxFlashT = 0, wxLightningT = 9;
function tickWeather(dt){ // sấm chớp khi giông (Gói B)
  const wx = weatherNow();
  if (!wx || wx.id !== 'storm'){ wxFlashT = Math.max(0, wxFlashT - dt); return; }
  wxLightningT -= dt;
  if (wxLightningT <= 0){ wxFlashT = 0.22; wxLightningT = rnd(8, 20); }
  wxFlashT = Math.max(0, wxFlashT - dt);
}

// ---------- Tia nắng & đèn lồng (Gói C) — screen-space ----------
// Bốn dải nắng nghiêng, trước đây vẽ bằng canvas với globalCompositeOperation='screen'. Chế độ
// hoà trộn 'screen' bỏ hẳn đường vẽ nhanh, và bốn hình này mỗi hình phủ trọn chiều cao màn hình:
// đo được BỎ RIÊNG hàm này đưa 22,5 → 39,2 FPS (+74%) — một hiệu ứng trang trí ăn hơn một phần ba
// khung hình. Chúng chỉ trôi ngang rất chậm, nên chuyển hẳn sang một lớp CSS có mix-blend-mode và
// animation riêng: trình duyệt ghép trên tầng compositor, lượt vẽ không tốn gì.

function drawLanternGlow(dk){ // đèn lồng Tương Dương về đêm — neo tọa độ thế giới
  const t = performance.now()/1000;
  ctx.save(); ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 12; i++){
    const sx = ((Math.sin(i*37.7)*0.5+0.5) * 0.86 + 0.07) * MAP.w - camera.x;
    const sy = ((Math.sin(i*53.3+7)*0.5+0.5) * 0.80 + 0.10) * MAP.h - camera.y;
    if (sx < -80 || sx > W+80 || sy < -80 || sy > H+80) continue;
    const fl = 0.75 + 0.25*Math.sin(t*6 + i*1.7);
    const r = 62 * fl;
    const g = ctx.createRadialGradient(sx, sy, 2, sx, sy, r);
    g.addColorStop(0, 'rgba(255,178,80,' + (0.44*dk*fl).toFixed(3) + ')');
    g.addColorStop(0.45, 'rgba(255,140,50,' + (0.18*dk*fl).toFixed(3) + ')');
    g.addColorStop(1, 'rgba(255,140,50,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(sx, sy, r, 0, 7); ctx.fill();
    ctx.fillStyle = 'rgba(255,210,130,' + (0.85*dk).toFixed(3) + ')';
    ctx.beginPath(); ctx.arc(sx, sy, 2.2, 0, 7); ctx.fill();
  }
  ctx.restore();
}

// ---------- Vùng nước theo map (tỉ lệ ảnh nền) — gợn sóng + lấp lánh (Gói F) ----------
const WATER_ZONES = {
  daohoa:    [ {fx:0.13, fy:0.20, frx:0.09, fry:0.10}, {fx:0.86, fy:0.24, frx:0.10, fry:0.11}, {fx:0.14, fy:0.82, frx:0.10, fry:0.11}, {fx:0.83, fy:0.80, frx:0.11, fry:0.12} ],
  tuyettinh: [ {fx:0.30, fy:0.33, frx:0.07, fry:0.05}, {fx:0.42, fy:0.45, frx:0.09, fry:0.06}, {fx:0.58, fy:0.66, frx:0.10, fry:0.07}, {fx:0.74, fy:0.88, frx:0.11, fry:0.08} ],
};
function drawWaterFx(){
  if (SETTINGS.lowFx) return;
  const zs = WATER_ZONES[curMap]; if (!zs) return;
  const t = performance.now()/1000;
  ctx.save();
  for (const z of zs){
    const zx = z.fx*MAP.w, zy = z.fy*MAP.h, zrx = z.frx*MAP.w, zry = z.fry*MAP.h;
    if (zx + zrx < camera.x || zx - zrx > camera.x+W || zy + zry < camera.y || zy - zry > camera.y+H) continue;
    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.beginPath(); ctx.ellipse(zx, zy, zrx, zry, 0, 0, 7); ctx.fill();
    for (let i = 0; i < 3; i++){
      const ph = ((t*0.35 + i/3) % 1);
      ctx.strokeStyle = 'rgba(255,255,255,' + (0.16*(1-ph)).toFixed(3) + ')';
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.ellipse(zx + Math.sin(t*0.6+i*2)*14, zy + Math.cos(t*0.5+i)*10, zrx*ph*0.9+6, zry*ph*0.9+4, 0, 0, 7); ctx.stroke();
    }
    for (let i = 0; i < 5; i++){
      const sx2 = zx + Math.sin(i*37.3 + zx)*zrx*0.7, sy2 = zy + Math.cos(i*51.7 + zy)*zry*0.6;
      const tw = Math.abs(Math.sin(t*2.2 + i*1.9));
      ctx.strokeStyle = 'rgba(255,255,240,' + (0.28*tw).toFixed(3) + ')'; ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(sx2-7*tw, sy2); ctx.lineTo(sx2+7*tw, sy2); ctx.stroke();
    }
  }
  ctx.restore();
}

function tickGameClock(dt){
  // Lịch Can Chi / Tứ Quý đã gỡ — đồng hồ nay chỉ chạy ngầm cho nhịp ngày/đêm
  // và thời tiết. Sự kiện neo theo GIỜ THẬT (xem Bảng Sự Kiện), không theo lịch game.
  const before = gameTimeInfo();
  player.gt.t += dt; _gtiCache = null;              // gt đổi → memo phải tính lại
  const after = gameTimeInfo();
  if (after.canh !== before.canh) calcDerived();     // nhịp ngày/đêm đổi (đêm +10% EXP)
  if (after.day !== before.day || after.month !== before.month || after.season.id !== before.season.id)
    spawnAmbients();                                 // sang ngày/mùa: roll thời tiết + hạt môi trường
}
function seasonAmbientCfg(cfg){ // hạt mùa phủ lên map ngoài trời — phó bản giữ than hồng
  if (typeof player === 'undefined' || !player || !player.gt) return cfg;
  if (curMap && curMap.startsWith('pb_')) return cfg;
  const sa = gameTimeInfo().season.amb;
  return { kind: sa.kind, color: sa.color, n: Math.max(cfg.n, sa.n) };
}
// Trộn nhiều lớp màu phẳng thành MỘT màu, thay vì tô chồng từng lớp lên cả màn hình.
function _skyMix(acc, r, g, b, a){
  if (a <= 0) return acc;
  const na = acc.a + a*(1 - acc.a);
  if (na <= 0) return acc;
  return { r:(r*a + acc.r*acc.a*(1-a))/na, g:(g*a + acc.g*acc.a*(1-a))/na,
           b:(b*a + acc.b*acc.a*(1-a))/na, a:na };
}
let _skyCss = '', _skyTick = 0;
function drawSkyOverlay(){ // screen-space — gọi sau vignette, trước zone banner
  if (!player || !player.gt) return;
  const gti = gameTimeInfo();
  const dk = skyDarkness();
  // Ngày/đêm · giao mùa · thời tiết đều là màu PHẲNG phủ trọn màn hình, và đổi rất chậm — trước
  // đây là tới NĂM lần fillRect(0,0,W,H) mỗi khung. Trộn sẵn thành một màu rồi giao cho một lớp
  // CSS: đo được bỏ riêng hàm này đưa 24,3 → 41,8 FPS.
  let acc = { r:0, g:0, b:0, a:0 };
  if (dk > 0){
    acc = _skyMix(acc, 8, 10, 32, 0.36*dk);
    if (dk > 0.85) acc = _skyMix(acc, 150, 170, 255, 0.05*dk);
  }
  if (gti.frac > gti.season.dusk - 0.05 && gti.frac < gti.season.dusk + 0.06)
    acc = _skyMix(acc, 255, 130, 50, 0.14*Math.max(0, 1 - Math.abs(gti.frac - gti.season.dusk)/0.06));
  if (gti.frac > gti.season.dawn - 0.06 && gti.frac < gti.season.dawn + 0.05)
    acc = _skyMix(acc, 255, 200, 110, 0.10*Math.max(0, 1 - Math.abs(gti.frac - gti.season.dawn)/0.06));
  if (dk === 0 && gti.season.id === 'ha')   acc = _skyMix(acc, 255, 225, 130, 0.06);
  if (dk === 0 && gti.season.id === 'dong') acc = _skyMix(acc, 190, 215, 240, 0.05);
  // ── Thời tiết động (Gói B) ──
  const wx = weatherNow();
  if (wx){
    if (wx.id === 'storm' || wx.id === 'drizzle') acc = _skyMix(acc, 26, 34, 52, wx.id === 'storm' ? 0.16 : 0.09);
    else if (wx.id === 'snow')                    acc = _skyMix(acc, 225, 235, 245, 0.07);
    else if (wx.id === 'sunhot' && dk === 0)      acc = _skyMix(acc, 255, 214, 120, 0.08);
    if (wx.id === 'fog')                          acc = _skyMix(acc, 214, 216, 210, 0.10);
    if (wxFlashT > 0)                             acc = _skyMix(acc, 235, 240, 255, Math.min(0.5, wxFlashT*2.6)); // chớp giông
  }
  const css = acc.a > 0.002
    ? `rgba(${Math.round(acc.r)},${Math.round(acc.g)},${Math.round(acc.b)},${acc.a.toFixed(3)})` : '';
  if (css !== _skyCss){
    _skyCss = css;
    const e = el('fx-sky');
    if (e){ e.style.background = css; e.style.opacity = css ? '1' : '0'; }
  }
  if (wx){
    if (wx.id === 'fog'){
      if (FXQ >= 1){
        const ft = performance.now()/1000;
        for (let i = 0; i < 3; i++){
          const fx0 = ((ft*16 + i*470) % (W + 800)) - 400, fy0 = H*(0.22 + i*0.26);
          const fg = ctx.createRadialGradient(fx0, fy0, 0, fx0, fy0, 360);
          fg.addColorStop(0, 'rgba(226,228,220,0.15)'); fg.addColorStop(1, 'rgba(226,228,220,0)');
          ctx.fillStyle = fg; ctx.beginPath(); ctx.arc(fx0, fy0, 360, 0, 7); ctx.fill();
        }
      }
    }
  }
  // ── Ánh sáng động (Gói C) ──
  if (_skyTick-- <= 0){ _skyTick = 30; fxRays(); }   // trời/thời tiết đổi theo phút, không theo khung
  if (dk > 0.15 && curMap === 'tuongduong' && FXQ >= 1 && typeof camera !== 'undefined') drawLanternGlow(dk);
}

function skillInfo(id){
  const sect = SECTS[player.sect];
  const d = SKILL_DEFS[id];
  if (!d) return null;
  const out = { id, icon: typeof d.icon==='function' ? d.icon(player.sect) : d.icon, desc: typeof d.desc==='function' ? d.desc(sect) : d.desc };
  if (d.kind==='sectA'){ out.name = sect.skillA.name; out.cd = sect.skillA.cd; out.qi = sect.skillA.qi; }
  else if (d.kind==='sectTP'){ out.name = sect.tp.name; out.cd = TP_CD; out.qi = player.level < 20 ? Math.round(TP_QI*0.7) : TP_QI; } // tân thủ <20: tuyệt chiêu -30% mana
  else if (d.kind==='vh'){ const _v = VOHOC_DEFS[id] || FUSION_DEFS[id]; out.name = _v.name; out.cd = _v.cd; out.qi = _v.qi; }
  else { out.name = d.name; out.cd = d.cd; out.qi = d.qi; }
  out.unlocked = player.level >= d.unlock && (!d.req || d.req());
  out.lockTxt = player.level < d.unlock ? `Mở khóa ở cấp ${d.unlock}` : (d.reqTxt || '');
  // hồi chiêu theo định nghĩa từng chiêu (dải 8-20s) — nhịp rõ để giọng hô tên chiêu không bị dồn
  return out;
}

