window.cheatExec = function(raw){
  const parts = (raw || '').trim().split(/\s+/);
  if (!parts[0]) return;
  const cmd = parts[0].toLowerCase().replace(/^\//, '');
  const num = (i, d) => { const v = parseFloat(parts[i]); return isNaN(v) ? d : v; };
  try {
    switch (cmd){
      case 'help': cheatHelp().forEach(l => cheatLog(l, l.startsWith('──') ? '#7fd4ff' : '#cfe8ff')); return;
      case 'max': applyTestBoost(); cheatLog('MAX MODE — mọi tính năng tối đa!', '#7ecbff'); break;
      case 'art': {
        const k = SPLASH_CFG[parts[1]] ? parts[1] : (player && player.sect) || 'thieulam';
        const v = (parts[2] || parts[1] || '').toLowerCase() === 'mavuong' ? 'mavuong' : null;
        window.openArtView(k, v);
        cheatLog(`Tranh: ${(SECTS[k] || {}).name || k}${v ? ' · set Ma Vương + cánh bậc 2' : ''}`, '#7ecbff');
        break;
      }
      case 'lv': {
        const n = clamp(Math.round(num(1, 1)), 1, 120);
        player.level = n; player.xp = 0; calcDerived(); player.hp = player.maxHp; player.qi = player.maxQi;
        cheatLog('Cấp → ' + n, '#8fd18f'); break;
      }
      case 'map': {
        const id = parts[1];
        if (!MAPS[id]){ cheatLog('Không có map "' + id + '". Xem /help', '#ff7a6a'); return; }
        curMap = id; DGN = null; buildWorld(); closePanels(); // bảng Chọn Trận của map cũ vẫn mở nếu không đóng
        const md = MAPS[id];
        if (md.dungeon) startDungeonRun(id);
        const sp = md.spawn || { x: MAP.w/2, y: MAP.h/2 };
        player.x = sp.x; player.y = sp.y; snapCamera();
        cheatLog('→ ' + md.name, '#8fd18f'); break;
      }
      case 'go': {
        player.x = clamp(num(1, player.x), 20, MAP.w - 20);
        player.y = clamp(num(2, player.y), 20, MAP.h - 20);
        snapCamera(); cheatLog('→ (' + Math.round(player.x) + ', ' + Math.round(player.y) + ')', '#8fd18f'); break;
      }
      case 'learn': {
        let _n = 0;
        for (const _vid in VOHOC_DEFS){ if (!vhLearned(_vid)){ player.vohoc[_vid] = true; _n++; } }
        calcDerived(); cheatLog('Đã học ' + _n + ' kỹ năng — cộng %Sát Thương vĩnh viễn (xem ở phím K)', '#ffb15c'); break;
      }
      case 'fullskill': {
        for (const _vid in VOHOC_DEFS) player.vohoc[_vid] = true;
        for (const _fid in FUSION_DEFS) player.vohoc[_fid] = true;
        player.skillLv = player.skillLv || {};
        for (const _sid in SKILL_DEFS) player.skillLv[_sid] = 120;
        player.bikipVH = Math.max(player.bikipVH || 0, 99);
        calcDerived();
        cheatLog(`FULL SKILL — ${Object.keys(VOHOC_DEFS).length} kỹ năng, ${Object.keys(SKILL_DEFS).length} chiêu cấp 120 (bấm K gán)`, '#ff9ae0'); break;
      }
      case 'bikip': {
        player.bikipVH = clamp(Math.round(num(1, 20)), 0, 999);
        cheatLog('Sách Kỹ Năng → ' + player.bikipVH, '#ffb15c'); break;
      }
      case 'tenui': {
        player.tenuiTT = 0;
        cheatLog('Đã gỡ Trọng Thương — có thể nhảy Vực Thẳm ngay', '#8fd18f'); break;
      }
      case 'time': { // /time [ngày] — nhảy thời gian thế giới (mặc định +10 ngày)
        gameClock();
        player.gt.t += Math.max(0, num(1, 10)) * GT_DAY;
        const gti = gameTimeInfo(); calcDerived(); spawnAmbients();
        // CANH_NAMES/gti.canh thuộc Lịch Thế Giới (Can Chi) đã gỡ — để lại thì gõ /time là
        // ném ReferenceError. Đồng hồ thế giới nay chỉ còn ngày/mùa.
        cheatLog(`Đồng Hồ Thế Giới → ${gti.season.name} ${gti.day}/${gti.month} Năm ${gti.year}`, gti.season.color); break;
      }
      case 'nd': case 'jewel': case 'gem': case 'hap': {
        // Bốn hệ tiền tệ ra đời sau bản console cũ nên trước đây không test được bằng lệnh nào.
        const v2 = Math.max(0, Math.round(num(1, 20)));
        if (cmd === 'nd'){ player.noidan = v2; player.ndDay = ''; player.ndCount = 0; cheatLog('Lõi Nguyên Tố → ' + v2 + ' (mở lại 3 lượt hấp thụ hôm nay)', '#b08ae8'); }
        else if (cmd === 'jewel'){ for (const k in JEWEL_NAMES) player.jewels[k] = v2; cheatLog('Tứ Châu → ' + v2 + ' mỗi loại', '#7ecbff'); }
        else if (cmd === 'gem'){ player.gems.tuLa = v2; player.gems.honNguyen = v2; cheatLog(`Tử La ${v2} · Hỗn Nguyên ${v2}`, '#e8552a'); }
        else { for (let t = 1; t < BAOHAP_TIERS.length; t++) player.baohap[t] = v2; cheatLog(`Box Kundun → ${v2} mỗi tầng (I-${BAOHAP_TIERS.length - 1})`, '#ffd76a'); }
        break;
      }
      case 'slot': {
        // Thanh chiêu 4 ô (phím 1-4) thêm vào sau bản console cũ — không có lệnh nào chạm tới.
        if (!parts[1]){ cheatLog('Thanh chiêu: ' + player.skillBar.map((x, i) => `${i+1}=${x || '—'}`).join(' · '), '#cfe8ff'); return; }
        const sl = clamp(Math.round(num(1, 1)), 1, 4) - 1;
        const sid = parts[2];
        if (!sid || sid === '-'){ player.skillBar[sl] = null; cheatLog(`Ô ${sl+1} → trống`, '#8fd18f'); }
        else if (!SKILL_DEFS[sid]){ cheatLog(`Không có chiêu "${sid}" — /fullskill rồi bấm K để xem danh sách`, '#ff7a6a'); return; }
        else { player.skillBar[sl] = sid; cheatLog(`Ô ${sl+1} → ${skName(sid)}`, '#8fd18f'); }
        break;   // thanh chiêu vẽ lại mỗi khung hình trong vòng lặp HUD, không cần gọi tay
      }
      case 'evo': {
        // Nhánh tiến hóa cũng vậy: chọn được trong game nhưng không set được từ console, nên test
        // một nhánh cụ thể phải cày tới đúng cấp mốc rồi bấm tay.
        const sid = parts[1], bac = clamp(Math.round(num(2, 1)), 1, EVO_LVS.length), path = parts[3];
        if (!SKILL_DEFS[sid] || !EVO_PATHS[path]){
          cheatLog(`/evo <id chiêu> <1-${EVO_LVS.length}> <${Object.keys(EVO_PATHS).join('|')}>`, '#ff7a6a'); return;
        }
        player.skillLv = player.skillLv || {};
        player.skillLv[sid] = Math.max(player.skillLv[sid] || 1, EVO_LVS[bac - 1]);  // phải đủ cấp mốc
        player.level = Math.max(player.level, player.skillLv[sid]);
        if (!player.skillEvo) player.skillEvo = {};
        if (!player.skillEvo[sid]) player.skillEvo[sid] = [];
        player.skillEvo[sid][bac - 1] = path;
        calcDerived();
        cheatLog(`${skName(sid)} bậc ${bac} → ${EVO_PATHS[path].name} (cấp chiêu ${player.skillLv[sid]})`, '#ffd76a'); break;
      }
      case 'silver': case 'khi': case 'shard': case 'manh': case 'tich': case 'dan': {
        const raw2 = parts[1] || '10000';
        const add = raw2.startsWith('+');
        const v = Math.abs(parseFloat(raw2)) || 0;
        const set = (get, put) => { const cur = get(); put(add ? cur + v : v); };
        if (cmd === 'silver') set(() => player.silver, x => player.silver = x);
        else if (cmd === 'shard') set(() => player.shard, x => player.shard = x);
        else if (cmd === 'dan') set(() => player.tienDan, x => player.tienDan = x);
        else if (cmd === 'khi') set(() => player.khi, x => player.khi = x);
        else if (cmd === 'manh') set(() => player.mats.manh, x => player.mats.manh = x);
        else if (cmd === 'tich') set(() => player.mats.tichMa, x => player.mats.tichMa = x);
        cheatLog('OK', '#8fd18f'); break;
      }
      case 'item': {
        const r = clamp(Math.round(num(1, 3)), 0, 4);
        const g = clamp(Math.round(num(2, 5)), 1, 10);
        const it = genItem(Math.min(100, (g-1)*10 + 10), 0, 'tranai');
        it.rarity = r; it.tier = g; it.level = (g-1)*10 + 10; it.perfect = false;
        rerollItemRarity(it);
        bagThem(it);
        cheatLog('+' + it.name + ' [' + giaiName(g) + ']', RARITIES[r].color); break;
      }
      case 'god': player._god = !player._god; cheatLog(player._god ? 'BẤT TỬ: BẬT' : 'BẤT TỬ: TẮT', '#7ecbff'); break;
      case 'kill': {
        const r = num(1, 350);
        const list = mobs.filter(m => !m.dead && dist(player.x, player.y, m.x, m.y) <= r);
        list.forEach(m => { m.hp = 0; killMob(m, 'cheat'); });
        cheatLog('Đã hạ ' + list.length + ' mục tiêu trong ' + r + 'px.', '#8fd18f'); break;
      }
      case 'th': {
        const sys = parts[1];
        const st = sys === 'amkhi' ? player.amkhiX : sys === 'bow' ? player.bow : sys === 'gangkhi' ? player.gangkhi : null;
        if (!st){ cheatLog('/th ' + Object.keys(TH_SYSTEMS).join('|') + ' <0-7>', '#ff7a6a'); return; }
        st.tier = clamp(Math.round(num(2, 1)), 0, 7); st.bless = 0;
        calcDerived(); cheatLog(`Thuần Thục ${TH_SYSTEMS[sys].name} → tầng ${st.tier}`, '#8fd18f'); break;
      }
      case 'dt': {
        // Mở bảng Đại Thành ngay, khỏi phải Tái Sinh thật để thử nghiệm.
        // Cũng phải nâng lvPeak: tab Đại Thành nằm sau cổng cấp tối đa (sysUnlocked), còn bảng
        // thì mở theo resetCount. Ngoài đời hai điều kiện luôn đi cùng nhau — chỉ có cheat mới
        // tách được chúng ra, và tách ra thì mở bảng bằng /dt xong lại không thấy tab đâu.
        player.lvPeak = Math.max(player.lvPeak || 1, MASTERY_LV);
        player.mongChiTon = true; player.mOpened = true;
        const n = clamp(Math.round(num(1, 200)), 0, 9999);
        player.mpts = n; player.mptsTotal = Math.max(player.mptsTotal || 0, n);
        calcDerived(); cheatLog(`${MASTERY_NAME}: mở bảng, ${n} điểm chưa dùng (bảng chứa ${masteryCap()})`, '#8fd18f');
        window.openMastery(); break;
      }
      case 'chi': {                       // /chi <id|all> — nhận Chimera · /ve <n> — thêm vé
        const C = chiState(), a = (parts[1] || '').toLowerCase();
        if (a === 'all'){ for (const c of CHIMERA){ C.co[c.id] = C.co[c.id] || { con:0 }; } C.eq = C.eq || 'aurelion'; C.out = true;
          cheatLog(`Nhận đủ ${CHIMERA.length} Chimera`, '#8fd18f'); }
        else if (CHI_MAP[a]){ chiNhan(a); C.eq = a; C.out = true; cheatLog(`Nhận ${CHI_MAP[a].ten} (C${C.co[a].con})`, '#8fd18f'); }
        else cheatLog('/chi <' + CHIMERA.map(c=>c.id).join('|') + '|all>', '#ff7a6a');
        calcDerived(); mountObj = null; break;
      }
      case 've': {
        const C = chiState(), n2 = clamp(Math.round(num(1, 10)), 0, 9999);
        C.ve.gk += n2; C.ve.cx += Math.round(n2/2);
        cheatLog(`+${n2} Ấn Giao Kết · +${Math.round(n2/2)} Ấn Cổ Xưa`, '#ffb15c'); break;
      }
      case 'boss': {
        const bd = BOSS_DEFS[curMap];
        if (!bd){ cheatLog('Map này không có trấn thủ.', '#ff7a6a'); return; }
        // /boss reset — dựng lại phong ấn. Cần vì /mo và /max phá sẵn phong ấn MỌI map để tới được
        // Cổng Vực, mà phá rồi thì không còn Vệ Binh Trụ nào để thử đánh.
        if ((parts[1] || '').toLowerCase() === 'reset'){
          delete player.bossKills[curMap];
          mobs = mobs.filter(m => !(m.def && m.def.bossKind));  // dọn boss vùng cũ rồi thả lại
          spawnZoneBosses();
          cheatLog(`Dựng lại phong ấn ${MAPS[curMap].name} — ${bd.thuve.length} Vệ Binh Trụ sống lại.`, '#c07fe0');
          break;
        }
        player.bossKills[curMap] = bd.thuve.map(t => t.id);
        player.x = bd.tranai.x * MAP.w - 380; player.y = bd.tranai.y * MAP.h; snapCamera();
        cheatLog('Đã mở phong ấn — dịch chuyển tới Cổng Vực.', '#c07fe0'); break;
      }
      case 'seal': {
        const n = clamp(Math.round(num(1, 0)), 0, 7);
        const order = ['daohoa','ngoai','chungnam','comoc','tuyettinh','mongco','nhanmon'];
        player.storyFlags = {};
        for (let i = 0; i < n; i++) player.storyFlags['ta_' + order[i]] = true;
        if (n >= 7){ player.storyFlags.ketMo = true; showKetMo(); }
        cheatLog(`Đã hạ ${n}/7 Tướng Quân · gỡ ${truDaGo()}/${TRU_TONG} Trụ Khoá.`, '#e8b060'); break;
      }
      case 'speed': {
        const mul = num(1, 1);
        player.speed = 190 * mul;
        cheatLog('Tốc chạy ×' + mul, '#8fd18f'); break;
      }
      case 'wipe': window.wipeSave(true); return;
      case 'deep': deepStart(); cheatLog('Tầng Sâu: bắt đầu', '#c07fe0'); return;
      case 'dat': {                      // /dat <n> — Đất Hồn nuôi Chimera
        const n = clamp(Math.round(num(1, 100)), 0, 99999);
        player.mats = player.mats || {}; player.mats.datHon = (player.mats.datHon || 0) + n;
        cheatLog(`+${n} Đất Hồn (tổng ${player.mats.datHon})`, '#b8e87a'); break;
      }
      case 'chilv': {                    // /chilv <cấp> — đặt thẳng cấp con đang xuất trận
        const C = chiState(); if (!C.eq){ cheatLog('Chưa chọn Chimera nào.', '#ff7a6a'); return; }
        const o = chiO(C.eq), n = clamp(Math.round(num(1, CHI_LV_MAX)), 1, CHI_LV_MAX);
        o.hoa = CHI_HOA.findIndex(t => t >= n); if (o.hoa < 0) o.hoa = CHI_HOA.length - 1;
        o.lv = n; o.xp = 0; calcDerived();
        cheatLog(`${CHI_MAP[C.eq].ten} → cấp ${n} (Hoá ${o.hoa}, mở ${chiKyMo(C.eq)}/4 kỹ năng)`, '#7ecbff'); break;
      }
      case 'cot': {                      // /cot <dòng|all> [n] — nhặt Cốt vào kho
        const a = (parts[1] || 'all').toLowerCase(), n = clamp(Math.round(num(2, 8)), 1, 200);
        const ds = a === 'all' ? COT_DONG_IDS : (COT_DONG[a] ? [a] : null);
        if (!ds){ cheatLog('/cot <' + COT_DONG_IDS.join('|') + '|all> [n]', '#ff7a6a'); return; }
        for (let i = 0; i < n; i++){
          const d = ds[i % ds.length], r = Math.random();
          cotKho().push(cotMoi(d, r < 0.3 ? 'co' : r < 0.7 ? 'tinh' : 'tho'));
        }
        cheatLog(`+${n} Cốt (kho ${cotKho().length}/${COT_KHO_MAX})`, '#b08ae8'); break;
      }
      case 'mo': {                       // /mo — mở HẾT cổng tiến trình, giữ nguyên sức mạnh
        moHetCong(); calcDerived();
        cheatLog(`Mở hết cổng: chính tuyến ${QUESTS.length}/${QUESTS.length} · cấp đỉnh ${lvPeak()} · phong ấn ${Object.keys(BOSS_DEFS).length} map · bảng ${MASTERY_NAME} mở (${player.mpts} điểm)`, '#7ecbff');
        cheatLog('Chưa gỡ Trụ Khoá nào — gõ /seal 7 nếu muốn xem Kết Mở.', '#9aa8d4'); break;
      }
      case 'quest': {                    // /quest <n|all> — nhảy thẳng tới một chương
        const a = (parts[1] || '').toLowerCase();
        if (a === 'all'){ moHetCong(); calcDerived();
          cheatLog(`Chính tuyến: xong toàn bộ ${QUESTS.length} nhiệm vụ.`, '#8fd18f'); break; }
        const n = clamp(Math.round(num(1, 1)), 1, QUESTS.length);
        questIdx = n - 1; questProg = 0; questState = 'active';
        player.mongChiTon = false;
        // Cấp phải theo kịp nhiệm vụ, nếu không mapGate lại chặn ngay ở cổng CẤP.
        const q = QUESTS[questIdx];      // QUESTS dùng `lv`, không phải `reqLv` (đó là của SIDE_QUESTS)
        if (player.level < q.lv){ player.level = q.lv; player.xp = 0; }
        player.lvPeak = Math.max(player.lvPeak || 1, player.level);
        // Phong ấn của các map thuộc chương TRƯỚC coi như đã phá — người chơi tới đây là đã qua đó.
        player.bossKills = player.bossKills || {};
        for (const m in MAPS){
          if (MAPS[m].reqMain && MAPS[m].reqMain < n && BOSS_DEFS[m])
            player.bossKills[m] = BOSS_DEFS[m].thuve.map(t => t.id);
        }
        calcDerived();
        cheatLog(`NV${n}/${QUESTS.length} — ${q.chapter || ''} · ${q.name} (cấp ${q.lv}, gặp ${q.npc || '?'})`, '#8fd18f');
        break;
      }
      case 'chuong': {                   // /chuong — liệt kê mốc nhiệm vụ của từng chương
        let ch = null;
        QUESTS.forEach((q, i) => {
          if (q.chapter && q.chapter !== ch){ ch = q.chapter;
            cheatLog(`  /quest ${i + 1}  →  ${ch} (cấp ${q.lv})`, '#cfe8ff'); }
        });
        cheatLog(`  /quest all  →  xong hết ${QUESTS.length} nhiệm vụ`, '#7ecbff');
        return;
      }
      case 'taisinh': {                  // /taisinh <n> — số vòng Tái Sinh, và điểm đi kèm
        const n = clamp(Math.round(num(1, 1)), 0, 99);
        player.resetCount = n;
        player.lvPeak = Math.max(player.lvPeak || 1, MAX_LV);
        player.mOpened = player.mOpened || n > 0;
        const them = MASTERY_PER_RESET * n;
        player.mpts = (player.mpts || 0) + them;
        player.mptsTotal = (player.mptsTotal || 0) + them;
        calcDerived();
        cheatLog(`Tái Sinh ×${n} → +${n * 2}% Công/Mạng vĩnh viễn · +${them} điểm ${MASTERY_NAME}`, '#ffd76a');
        break;
      }
      case 'tang': {                     // /tang <n> — nhảy thẳng tới tầng n của Tầng Sâu
        const n = clamp(Math.round(num(1, 10)), 1, 999);
        if (!DEEP) deepStart();
        if (!DEEP){ cheatLog('Không vào được Tầng Sâu (cần cấp 20).', '#ff7a6a'); return; }
        let canh = 0;
        while (DEEP && DEEP.floor < n && canh++ < 1000){
          const truoc = DEEP.floor; deepNextFloor();
          if (!DEEP || DEEP.floor === truoc) break;   // không nhích được thì dừng, đừng treo game
        }
        cheatLog('Tầng Sâu: tầng ' + (DEEP ? DEEP.floor : 0), '#c07fe0'); return;
      }
      case 'obstacles': window.SHOW_OBSTACLES = !window.SHOW_OBSTACLES; cheatLog('Debug obstacle overlay: ' + (window.SHOW_OBSTACLES ? 'ON' : 'OFF'), '#cfe8ff'); return;
      default: cheatLog('Lệnh lạ "' + cmd + '" — gõ /help', '#ff7a6a'); return;
    }
    try { saveGame(); } catch { /* best-effort — bỏ qua nếu lỗi */ }
  } catch (e){ cheatLog('Lỗi: ' + e.message, '#ff7a6a'); }
};

// ---------- Main loop ----------
// ═══════════ CHẤT LƯỢNG HIỂN THỊ TỰ DÒ ═══════════
// Đo được trên máy không GPU rời: 22 FPS ở bãi quái, mà update()+render() chỉ tốn 2,5ms JS —
// gần 48ms còn lại là RASTER, không phải logic. Bịt riêng shadowBlur trong drawPlayer() đưa 22
// lên 35,7 FPS (+60%): một nhân vật duy nhất đặt shadowBlur 21 lần cho 203 nhát fill, mà mỗi
// nhát có bóng là Chromium phải vẽ ra mặt phụ, làm mờ, rồi ghép lại.
//   FXQ 2 = đầy · 1 = vừa (tắt quầng sáng nhân vật, tắt vignette) · 0 = thấp (thêm: bỏ hạt, bỏ cỏ)
let FXQ = 2;
let FXQ_AUTO = true;          // người chơi chọn tay trong Cài Đặt thì thôi tự dò
const _fxT = []; let _fxHold = 0;
function fxShadow(color, blur){   // mọi quầng sáng trong lượt vẽ THẾ GIỚI đi qua đây
  if (FXQ >= 2){ ctx.shadowColor = color; ctx.shadowBlur = blur; }
}
function fxShadowOff(){ if (ctx.shadowBlur) ctx.shadowBlur = 0; }
function fxAutoTune(ms){
  if (!FXQ_AUTO || !player || dead) return;
  if (_fxHold > 0){ _fxHold--; return; }
  _fxT.push(ms); if (_fxT.length < 90) return;
  const med = _fxT.slice().sort((a,b)=>a-b)[45];
  _fxT.length = 0;
  // Hạ nhanh, nâng chậm và phải dư sức RÕ RỆT — không thì FXQ nhấp nháy quanh ngưỡng, mà đổi
  // chất lượng giữa trận còn khó chịu hơn là thấp đều.
  // Độ nét trên MỨC NỀN (mức nét bằng bản cũ) là phần THÊM, nên đuối thì trả nó lại
  // TRƯỚC KHI hi sinh hiệu ứng. Không có nhánh này thì bộ tự chỉnh leo lên 2× rồi tắt
  // sạch quầng sáng để nuôi độ nét — đúng ngược thứ tự ưu tiên đã đặt ra bên dưới.
  if (RES_AUTO && med > 19){
    const floor = resFloorForDpr(), ri0 = RES_STEPS.indexOf(RES);
    if (RES > floor + 1e-6 && ri0 >= 0 && ri0 < RES_STEPS.length - 1){
      resSet(RES_STEPS[ri0 + 1], true); return;
    }
  }
  const was = FXQ;
  if (med > 30 && FXQ > 0) FXQ--;
  else if (med > 21 && FXQ > 1) FXQ--;
  else if (med < 13 && FXQ < 2) FXQ++;
  if (FXQ !== was){ SETTINGS.lowFx = FXQ === 0; _fxHold = FXQ > was ? 600 : 240; fxApply(); fxNote(); return; }
  // Hiệu ứng đã kịch mức Thấp mà vẫn không đủ 60 → hạ độ phân giải. Đây là thứ tự CỐ Ý: hiệu ứng
  // mất đi thì người chơi không thấy thiếu, còn hạ độ phân giải là chữ mềm đi — trả giá sau cùng.
  if (!RES_AUTO) return;
  const ri = RES_STEPS.indexOf(RES), i = ri < 0 ? 0 : ri;
  if (med > 19 && FXQ === 0 && i < RES_STEPS.length - 1) resSet(RES_STEPS[i + 1], true);
  else if (med < 13 && i > 0 && FXQ >= 2) resSet(RES_STEPS[i - 1], true);
}
// Đổi độ phân giải. `auto` chỉ để phân biệt người chơi tự chọn (ghi vào Cài Đặt) với bộ tự chỉnh.
function resSet(v, auto){
  const was = RES;
  RES = clamp(+v || 1, 0.5, 1);
  if (!auto){ RES_AUTO = false; SETTINGS.res = RES; saveSettings(); }
  if (RES !== was){
    resize();
    _fxHold = RES > was ? 600 : 240;   // nâng lên thì giữ lâu hơn, tránh nhấp nháy quanh ngưỡng
    if (auto && player) addFloat(player.x, player.y - 86,
      `⚙ Độ nét: ${Math.round(RES*100)}% (tự chỉnh theo máy — đổi tay ở Cài Đặt)`, '#8ab4ff', 12);
  }
  if (!auto) renderSettings();
}
window.setRes = function(v){
  if (v === 'auto'){ RES_AUTO = true; SETTINGS.res = 'auto'; saveSettings(); renderSettings(); return; }
  resSet(+v, false);
};
window.setFxq = function(v){
  if (v === 'auto'){ FXQ_AUTO = true; }
  else { FXQ_AUTO = false; FXQ = clamp(+v, 0, 2); }
  SETTINGS.fxq = FXQ_AUTO ? 'auto' : FXQ;
  SETTINGS.lowFx = FXQ === 0;   // giữ cho các chỗ cũ còn đọc lowFx
  saveSettings(); fxApply(); renderSettings();
};
function fxLoad(){
  const v = SETTINGS.fxq;
  if (v === undefined || v === 'auto'){ FXQ_AUTO = true; FXQ = SETTINGS.lowFx ? 0 : 2; }
  else { FXQ_AUTO = false; FXQ = clamp(+v, 0, 2); SETTINGS.lowFx = FXQ === 0; }
  const r = SETTINGS.res;
  if (r === undefined || r === 'auto'){ RES_AUTO = true; }
  else { RES_AUTO = false; RES = clamp(+r, 0.5, 1); }
  resize();
  fxApply();
}
function fxNote(){
  const t = ['Thấp','Vừa','Đầy'][FXQ];
  addFloat(player.x, player.y-86, `⚙ Hiệu ứng: ${t} (tự chỉnh theo máy — đổi tay ở Cài Đặt)`, '#8ab4ff', 12);
}
function fxApply(){   // đồng bộ lớp phủ CSS theo FXQ + bản đồ hiện tại
  const md0 = player ? mapDef() : null;
  const dark = !!(md0 && md0.dark);
  const v = el('fx-vignette'); if (v) v.classList.toggle('on', FXQ >= 1 && !dark);
  const d = el('fx-dark');     if (d) d.classList.toggle('on', dark);
  fxRays();
}
// Nắng chỉ chiếu ban ngày, ngoài thành, và chỉ ở mức hiệu ứng Đầy.
function fxRays(){
  const e = el('fx-rays'); if (!e || !player) return;
  const md0 = mapDef(), wx = weatherNow();
  e.classList.toggle('on', FXQ >= 2 && skyDarkness() === 0 && !md0.city && !md0.dark
                           && (!wx || wx.id === 'sun' || wx.id === 'sunhot'));
}
// Ghi opacity là việc của tầng ghép ảnh, không phải của tầng tô điểm ảnh — rẻ hơn fillRect toàn
// màn hình vài bậc. Chỉ ghi khi giá trị đổi thật, để khỏi làm bẩn style mỗi khung.
const _fxOv = {};
// Ghi số Trụ Khoá đã gỡ vào lớp #fx-crack. Chỉ ghi khi ĐỔI — mỗi lần ghi lại thuộc tính là một
// lần trình duyệt tính lại kiểu, mà giá trị này thay đổi đúng năm lần trong cả ván chơi.
let _nutTru = -1;
function capNhatVetNut(){
  const n = SETTINGS.lowFx ? 0 : truDaGo();
  if (n === _nutTru) return;
  _nutTru = n;
  const e = el('fx-crack'); if (e) e.dataset.tru = n;
}
function fxOverlay(id, k){
  const v = Math.max(0, Math.min(1, k)).toFixed(2);
  if (_fxOv[id] === v) return;
  _fxOv[id] = v;
  const e = el(id); if (e) e.style.opacity = v;
}
let _fxPrev = 0;
// ── Bảng đo hiệu năng (bật ở Cài Đặt) ────────────────────────────────────────
// Tách rõ hai phần, vì chúng nằm ở hai nơi khác nhau của máy:
//   JS     = thời gian CPU chạy update()+render() để GỬI lệnh vẽ — có card đồ hoạ hay không cũng vậy
//   RASTER = thời gian TÔ điểm ảnh, xảy ra SAU khi render() trả về — hoàn toàn do card đồ hoạ
// Máy dựng game này chạy phần mềm giả lập card (SwiftShader, ~634 triệu điểm ảnh/giây) nên raster
// chiếm 89-93% mỗi khung. Trên máy có card thật, phần đó rẻ hơn hàng chục lần — bảng này để người
// chơi tự đọc số trên MÁY CỦA HỌ thay vì tin vào số đo ở máy dựng.
const _perf = { js: [], frame: [], fps: 0, ms: 0, jsMs: 0, rasMs: 0, t: 0 };
function perfSample(jsMs, frameMs){
  _perf.js.push(jsMs); _perf.frame.push(frameMs);
  if (_perf.js.length < 30) return;
  const med = a2 => { const x = a2.slice().sort((u,v)=>u-v); return x[x.length>>1]; };
  _perf.jsMs = +med(_perf.js).toFixed(2);
  _perf.ms   = +med(_perf.frame).toFixed(2);
  _perf.rasMs = +Math.max(0, _perf.ms - _perf.jsMs).toFixed(2);
  _perf.fps  = +(1000/_perf.ms).toFixed(1);
  _perf.js.length = 0; _perf.frame.length = 0;
}
function drawPerfHud(){
  if (!SETTINGS.perfHud || !_perf.fps) return;
  const L = [
    `${_perf.fps} FPS  ·  ${_perf.ms} ms/khung`,
    `JS ${_perf.jsMs} ms  ·  raster ${_perf.rasMs} ms`,
    `hiệu ứng ${['Thấp','Vừa','Đầy'][FXQ]}${FXQ_AUTO ? '*' : ''}  ·  độ nét ${Math.round(RES*100)}%${RES_AUTO ? '*' : ''}  ·  sprite ${_hsCache.size}  ·  ảnh ${window.anhDangGiuMB ? window.anhDangGiuMB() : '?'} MB`,
  ];
  ctx.save();
  ctx.font = 'bold 11.5px ui-monospace, Menlo, Consolas, monospace';
  const w = Math.max(...L.map(t => ctx.measureText(t).width)) + 16;
  // Góc TRÁI-TRÊN, ngay dưới khối tên/bình thuốc/giờ. Đã thử góc phải (đè lên hai nút PK và AUTO) rồi
  // góc trái-dưới — chỗ đó đè lên Nhật Ký Chiến Đấu, vốn cao tới 22vh nên trên màn hình thấp thì
  // mép trên của nó leo lên tận giữa màn. Trái-trên là dải duy nhất cố định và luôn trống.
  const x0 = 12, y0 = 112;
  ctx.fillStyle = 'rgba(8,9,20,.82)';
  ctx.beginPath(); ctx.roundRect(x0, y0, w, 58, 7); ctx.fill();
  ctx.strokeStyle = 'rgba(126,203,255,.35)'; ctx.lineWidth = 1; ctx.stroke();
  ctx.textAlign = 'left';
  ctx.fillStyle = _perf.fps >= 55 ? '#6ae88a' : _perf.fps >= 40 ? '#ffd76a' : '#ff8f6b';
  ctx.fillText(L[0], x0 + 8, y0 + 17);
  ctx.fillStyle = '#9aa8d4';
  ctx.fillText(L[1], x0 + 8, y0 + 33);
  ctx.fillText(L[2], x0 + 8, y0 + 49);
  ctx.restore();
}
function loop(now){
  requestAnimationFrame(loop); // schedule first — an error can never freeze the game
  const dt = Math.min(0.05, (now - lastTime)/1000);
  lastTime = now;
  const _t0 = performance.now();
  // Hoạt ảnh Khế Ước phủ kín màn và chạy tới ~35 giây cho lượt ×10. Nếu thế giới vẫn chạy phía
  // sau thì nhân vật đứng chết trân hứng đòn suốt chừng đó — đo bằng cách quay lại một lượt thật:
  // chết ngay giữa lượt quay. Dừng hẳn update() trong lúc quay; render() vẫn chạy để khung hình
  // dưới lớp phủ không đóng băng cứng khi bỏ qua hoạt ảnh.
  try { if (!_kuChay) update(dt); render(); drawPerfHud(); } catch(e){ console.error(e); }
  const _js = performance.now() - _t0;
  // Đo bằng KHOẢNG CÁCH GIỮA HAI KHUNG, không phải thời gian chạy update+render: phần đắt nhất
  // là raster, xảy ra SAU khi render() trả về, nên đo trong thân hàm sẽ không thấy gì cả.
  if (_fxPrev){ fxAutoTune(Math.min(200, now - _fxPrev)); perfSample(_js, Math.min(200, now - _fxPrev)); }
  _fxPrev = now;
}
requestAnimationFrame(loop);

// ============================================================
// V2 — UI/UX: khung Nhân Vật gộp tab · Taskbar 5 kỹ năng ·
// Túi Đồ có hình · Bản Đồ thế giới · NPC · PK/Tội Ác
