const PERSONALITIES = {
  chinh: { name:'Ngay Thẳng', glyph:'⚖', desc:'Nói sao làm vậy. Dân Lunaris City chào ngươi trước khi ngươi kịp chào.' },
  ta:    { name:'Tàn Nhẫn',   glyph:'☾', desc:'Việc cần làm thì làm, không hỏi giá. Kẻ khác tránh đường ngươi vì sợ, không vì nể.' },
  trung: { name:'Điềm Tĩnh',  glyph:'◑', desc:'Không ngả về bên nào cho tới khi biết đủ. Ít bạn, mà cũng ít kẻ thù.' },
};
function rollTrait(excludeIds){
  const pool = TRAITS.filter(t => !excludeIds.includes(t.id));
  let total = 0;
  for (const t of pool) total += TRAIT_TIERS[t.tier].w;
  let r = Math.random() * total;
  for (const t of pool){ r -= TRAIT_TIERS[t.tier].w; if (r <= 0) return t; }
  return pool[pool.length - 1];
}
function rollTraitsSilent(){
  const ids = [];
  for (let i = 0; i < 3; i++) ids.push(rollTrait(ids).id);
  return ids;
}

// ---------- Danh tính phiêu bạt: đặt tên nhân vật ----------
const NAME_HO = ['Sparkden','Waverly','Emberfall','Glimmerwood','Driftholt','Ashgrove','Moonshale','Thistledown','Brambleton','Frostholt','Silverfen','Oakhollow','Windmere','Starholt','Cinderfell','Duskrider','Hatchbrook','Shellmere','Cloudvane','Rootwyn'];
const NAME_TEN = ['Robin','Sage','Rowan','Lark','Fenn','Wynn','Quinn','Reed','Sorrel','Vale','Ren','Merit','Sterling','Marlowe','Ellery','Winter','Hollis','Faye','Cove','Bryn','Osric','Thalia','Corin','Dashiell'];
function genCharName(){
  const ho = NAME_HO[(Math.random()*NAME_HO.length)|0];
  const ten = NAME_TEN[(Math.random()*NAME_TEN.length)|0];
  return ho + ' ' + ten;
}
function sanitizeCharName(v){
  return (v || '').replace(/[<>&"'`]/g, '').replace(/\s+/g, ' ').trim().slice(0, 24);
}

// ═══════════ TẠO NHÂN VẬT — kiểu MU Online ═══════════
// Màn cũ là "Thẻ Tiên Duyên": 16 lá bài úp, mỗi lá vẽ THÁI CỰC bao quanh BÁT QUÁI, lật ra để roll
// 3 mảnh vận mệnh, kèm ô chọn tính cách "hài hòa âm dương". Đó là thứ ĐẦU TIÊN người chơi mới
// nhìn thấy, và nó vi phạm Quy tắc 1 đúng ở chỗ dễ thấy nhất. MU Online không có bước đó: chọn
// lớp, gõ tên, vào game. Làm đúng như vậy.
// Ba mảnh thiên phú vẫn còn (chúng gắn với nhiều hệ thống khác) — nay roll ngầm trong startGame()
// qua rollTraitsSilent(), đúng như đường quick-start vẫn dùng lâu nay.
let ccSect = null;
const CC_ORDER = ['thieulam','toanchan','baidasan','minhgiao','bug'];

// ═══════════ NĂM Ô NHÂN VẬT ═══════════
// MU cho mỗi tài khoản năm ô. Màn chờ liệt kê cả năm: ô có người thì chọn rồi Vào Game, ô trống
// thì bấm là sang màn tạo. Xoá nhân vật CHỈ có ở đây — trong game không có đường nào tới nó, vì
// bấm nhầm giữa lúc đang chơi là mất một nhân vật cấp 100 và không có đường hoàn tác.
let ccSlot = -1;    // ô đang được chọn trên màn chờ
let ccHoiXoa = -1;  // ô đang hỏi lại trước khi xoá; -1 = không hỏi ai
function ccKhiNao(t){
  if (!t) return '';
  const d = Math.floor((Date.now() - t) / 86400000);
  if (d <= 0){
    const h = Math.floor((Date.now() - t) / 3600000);
    return h <= 0 ? 'vừa xong' : h + ' giờ trước';
  }
  return d === 1 ? 'hôm qua' : d + ' ngày trước';
}
function ccSlotsRender(){
  const wrap = el('cc-slots'); if (!wrap) return;
  const slots = danhSachO();
  if (ccSlot >= 0 && !slots[ccSlot]) ccSlot = -1;
  if (ccSlot < 0) ccSlot = slots.findIndex(Boolean);
  wrap.innerHTML = '';
  slots.forEach((sv, i) => {
    const row = document.createElement('div');
    if (!sv || !sv.player){
      row.className = 'cc-slot empty';
      row.setAttribute('role', 'button'); row.tabIndex = 0;
      row.innerHTML = `<span class="cc-slot-add">+</span><span class="cc-slot-nm">Ô trống — tạo nhân vật mới</span>`;
      const mo = () => { AudioSys.sfx('ui', 0.5); openCreate(i); };
      row.addEventListener('click', mo);
      row.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); mo(); } });
      wrap.appendChild(row); return;
    }
    const pl = sv.player;
    const sc = SECTS[pl.sect] || {};
    if (ccHoiXoa === i){
      // Hỏi lại NGAY TRÊN DÒNG ĐÓ, không dùng confirm() của trình duyệt: hộp thoại hệ thống
      // không nói được tên và cấp của nhân vật sắp mất, mà đó chính là thứ cần đọc trước khi bấm.
      row.className = 'cc-slot hoi-xoa';
      row.innerHTML = `<div class="cc-slot-txt"><div class="cc-slot-nm">Xóa <b>${pl.name || '—'}</b> · Cấp ${pl.level || 1}?</div>
        <div class="cc-slot-sub">Nhân vật này biến mất vĩnh viễn — không có đường hoàn tác.</div></div>`;
      const yes = document.createElement('button');
      yes.className = 'cc-slot-yes'; yes.type = 'button'; yes.textContent = 'Xóa vĩnh viễn';
      yes.addEventListener('click', ev => { ev.stopPropagation();
        xoaNhanVat(i); ccHoiXoa = -1; if (ccSlot === i) ccSlot = -1;
        AudioSys.sfx('ui', 0.6); ccSlotsRender();
      });
      const no = document.createElement('button');
      no.className = 'cc-slot-no'; no.type = 'button'; no.textContent = 'Hủy';
      no.addEventListener('click', ev => { ev.stopPropagation(); ccHoiXoa = -1; ccSlotsRender(); });
      row.appendChild(yes); row.appendChild(no);
      wrap.appendChild(row); return;
    }
    row.className = 'cc-slot' + (ccSlot === i ? ' sel' : '');
    row.setAttribute('role', 'button'); row.tabIndex = 0;
    const noi = (MAPS[sv.curMap] && MAPS[sv.curMap].name) || '—';
    row.innerHTML = `<img class="cc-slot-art" src="${heroCardUrl(pl.sect)}" alt="" onerror="this.style.visibility='hidden'">
      <div class="cc-slot-txt">
        <div class="cc-slot-nm">${pl.name || '—'}</div>
        <div class="cc-slot-sub">Cấp <b>${pl.level || 1}</b> · <span style="color:${sc.color || 'var(--text-dim)'}">${sc.name || '—'}</span></div>
        <div class="cc-slot-loc">${noi}${sv.savedAt ? ' · ' + ccKhiNao(sv.savedAt) : ''}</div>
      </div>`;
    const chon = () => { ccSlot = i; ccHoiXoa = -1; AudioSys.sfx('ui', 0.5); ccSlotsRender(); };
    row.addEventListener('click', chon);
    row.addEventListener('dblclick', () => { ccSlot = i; el('btn-continue').click(); });
    row.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); chon(); } });
    const del = document.createElement('button');
    del.className = 'cc-slot-del'; del.type = 'button'; del.title = 'Xóa nhân vật này';
    del.setAttribute('aria-label', 'Xóa nhân vật ' + (pl.name || ''));
    del.textContent = '✕';
    del.addEventListener('click', ev => { ev.stopPropagation(); ccHoiXoa = i; ccSlotsRender(); });
    row.appendChild(del);
    wrap.appendChild(row);
  });
  const day = slots.every(Boolean);
  { const b = el('btn-newchar');
    if (b){ b.classList.remove('hidden'); b.style.display = day ? 'none' : ''; b.textContent = 'Tạo Nhân Vật Mới'; } }
  { const b = el('btn-continue');
    if (b) b.classList.toggle('hidden', ccSlot < 0); }
  { const n = el('cc-slots-note');
    if (n) n.textContent = day
      ? 'Đã đủ 5 nhân vật — xóa một ô nếu muốn tạo thêm.'
      : `${slots.filter(Boolean).length}/${MAX_CHARS} ô đã dùng.`; }
}
function ccRender(){
  const wrap = el('cc-classes'); if (!wrap) return;
  wrap.innerHTML = '';
  for (const k of CC_ORDER){
    const sc = SECTS[k]; if (!sc) continue;
    const d = document.createElement('div');
    d.className = 'cc-card' + (ccSect === k ? ' sel' : '');
    d.setAttribute('role', 'button');
    d.tabIndex = 0;
    d.innerHTML = `<img class="cc-art" src="${heroCardUrl(k)}" alt="">
      <div class="cc-nm" style="color:${sc.color}">${sc.name}</div>
      <div class="cc-tag">${sc.role || ''}</div>`;
    const pick = () => { ccSect = k; AudioSys.sfx('ui', 0.5); ccRender(); };
    d.addEventListener('click', pick);
    d.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); pick(); } });
    wrap.appendChild(d);
  }
  // Bản phóng to của lớp đang chọn — dùng ĐÚNG hình nhân vật của game (heroCardUrl), thứ
  // người chơi sẽ thấy suốt cả hành trình. Bản chibi từng được thử ở đây rồi bỏ vì không hợp
  // tông; bản minh hoạ vẫn giữ, xem bằng lệnh /art.
  const spl = el('cc-splash');
  if (spl){
    if (ccSect){ spl.src = heroCardUrl(ccSect); spl.classList.remove('hidden'); requestAnimationFrame(() => spl.classList.add('on')); }
    else { spl.classList.remove('on'); spl.classList.add('hidden'); }
  }
  const det = el('cc-detail');
  if (det){
    const sc = ccSect && SECTS[ccSect];
    det.innerHTML = sc
      ? `<b style="color:${sc.color}">${sc.name}</b> — ${sc.desc || ''}
         <div class="cc-skills">Chiêu chính: <b>${(sc.skillA||{}).name || '—'}</b> · Trấn Phái: <b>${(sc.tp||{}).name || '—'}</b></div>`
      : '<span style="opacity:.6">Chọn một lớp để xem chi tiết.</span>';
  }
  ccValidate();
}
function ccValidate(){
  const inp = el('inp-char-name'), btn = el('btn-create'), warn = el('cc-name-warn');
  if (!inp || !btn) return;
  const nm = sanitizeCharName(inp.value);
  let msg = '';
  if (!ccSect) msg = 'Hãy chọn một lớp.';
  else if (!nm) msg = 'Hãy đặt tên cho nhân vật.';
  else if (nm.length < 2) msg = 'Tên cần ít nhất 2 ký tự.';
  btn.disabled = !!msg;
  if (warn) warn.textContent = msg;
}
let ccOMoi = -1;   // ô sẽ nhận nhân vật vừa tạo
function openCreate(o){
  ccSect = null;
  ccOMoi = (typeof o === 'number' && o >= 0) ? o : oTrongDauTien();
  if (ccOMoi < 0) return;   // đủ năm ô — không còn chỗ nào để tạo
  el('sect-select').classList.remove('hidden'); titleStart();
  // showMainMenu() ẩn hết phần tạo nhân vật đi (người cũ chỉ thấy danh sách ô) — bật lại toàn bộ,
  // nếu không thì bấm "Tạo nhân vật mới" từ màn chờ ra một trang trống.
  for (const _id of ['cc-classes','cc-detail','btn-create','cc-name-warn']){ const _e = el(_id); if (_e) _e.style.display = ''; }
  { const _n = document.querySelector('#sect-select .cc-name'); if (_n) _n.style.display = ''; }
  const cards = el('cc-classes'); if (cards) cards.style.display = '';
  // Danh sách ô và hai nút của nó thuộc về màn chờ, không thuộc màn tạo.
  { const _sl = el('cc-slots'); if (_sl) _sl.style.display = 'none'; }
  for (const _id of ['btn-continue','btn-newchar']){ const _e = el(_id); if (_e) _e.classList.add('hidden'); }
  // Chỉ có đường quay lại khi đã có nhân vật để quay về. Người chơi mới tinh không có gì phía sau.
  { const _b = el('cc-back'); if (_b) _b.style.display = soNhanVat() > 0 ? '' : 'none'; }
  const sub = document.querySelector('#sect-select .ss-sub');
  if (sub) sub.innerHTML = 'Bầu trời nứt ra, và ngươi rơi qua. Ký ức võ nghệ ở lại phía bên kia.<br>Chọn lại con đường của mình — rồi đi sửa thứ thế giới ngươi vừa làm hỏng.';
  const inp = el('inp-char-name');
  if (inp && !inp.value) inp.value = genCharName();
  ccRender();
}
{
  const inp = el('inp-char-name');
  if (inp) inp.addEventListener('input', ccValidate);
  const rnd = el('btn-name-random');
  if (rnd) rnd.addEventListener('click', ()=>{ el('inp-char-name').value = genCharName(); AudioSys.sfx('ui', 0.5); ccValidate(); });
  const go = el('btn-create');
  if (go) go.addEventListener('click', ()=>{
    if (!ccSect) return;
    // Ô đích phải chốt TRƯỚC startGame: activeSlot có thể còn trỏ vào nhân vật vừa chơi xong,
    // và saveGame() ở cuối startGame sẽ ghi đè đúng ô đó.
    const o = (ccOMoi >= 0 && !danhSachO()[ccOMoi]) ? ccOMoi : oTrongDauTien();
    if (o < 0) return;   // đủ năm ô
    activeSlot = o; ccOMoi = -1;
    const nm = sanitizeCharName(el('inp-char-name').value) || genCharName();
    el('sect-select').classList.add('hidden'); titleStop();
    startGame(ccSect, { name: nm });
    checkTitles();
    AudioSys.sfx('quest', 0.9);
  });
  const back = el('cc-back');
  if (back) back.addEventListener('click', ()=>{ ccOMoi = -1; AudioSys.sfx('ui', 0.5); showMainMenu(); });
  const nc = el('btn-newchar');
  if (nc) nc.addEventListener('click', ()=>{ AudioSys.sfx('ui', 0.5); openCreate(); });
}

// Danh hiệu ẩn cũ mở bằng cách lật đủ 3 mảnh HUYỀN ở màn Thẻ Tiên Duyên — màn đó đã gỡ, nay
// mở khi ba thiên phú roll ngầm đều từ bậc HUYỀN trở lên (cùng điều kiện, chỉ khác đường tới).
TITLES.push({ id:'tmsq', name:'Kẻ Được Định Mệnh Chọn', cond:p=>!!p.quzeTitle, stats:{ allPct:0.03 }, vfx:null });

// ═══════════ A2: KHÁM PHÁ — sự kiện ngẫu nhiên khi đi đường (vận may trên đường) ═══════════
let kyngoAcc = 0, kyngoNext = rnd(14000, 22000), kyngoPrev = null; // ~75-115s đi bộ
function updateKyngo(_dt){ // đi theo quãng đường di chuyển, không cần dt — giữ tham số cho đồng bộ chữ ký update*(dt)
  if (!player || dead || mapDef().dungeon) { kyngoPrev = null; return; }
  if (kyngoPrev){
    const moved = dist(player.x, player.y, kyngoPrev.x, kyngoPrev.y);
    if (moved < 20) kyngoAcc += moved; // <20px/frame: loại teleport
    if (kyngoAcc >= kyngoNext){
      kyngoAcc = 0; kyngoNext = rnd(14000, 22000);
      rollKyngo();
    }
  }
  kyngoPrev = { x:player.x, y:player.y };
}
function rollKyngo(){
  const r = Math.random();
  const mdK = mapDef();
  let text, sub, color = '#7ecbff';
  if (r < 0.20){ // Học giả lang thang tặng mảnh cổ thư
    const p = Math.floor(Math.random()*3);
    player.bikip.pieces[p]++;
    text = 'KHÁM PHÁ · Học Giả Lang Thang'; sub = `"Bằng hữu hữu duyên, tặng ngươi Mảnh Cổ Thư ${TAN_QUYEN[p]}!"`; color = '#e84a6a';
  } else if (r < 0.36){ // Mạch Lumen
    const n = (2 + Math.floor(Math.random()*2)) * GO_HUYENTHIET;
    player.silver += n;
    text = 'KHÁM PHÁ · Khoáng Mạch'; sub = `Đá dưới chân lóe sáng — đãi được ${n.toLocaleString('vi-VN')}◈ Lumen!`; color = '#9fd0ff';
  } else if (r < 0.48){ // Hồ lô lạc
    if (player.potions < 5){ player.potions++; sub = 'Nhặt được 1 🧪 Bình Thuốc Đỏ còn nguyên!' ; }
    else { player.silver += 100; sub = 'Hồ lô đầy — đổi lấy 100◈!'; }
    text = 'KHÁM PHÁ · Bình Thuốc Rơi';
  } else if (r < 0.64 && mdK.type !== 'safe'){ // Mai phục — khu an toàn tuyệt đối không có
    const mobType = (mdK.packs && mdK.packs.length) ? mdK.packs[Math.floor(Math.random()*mdK.packs.length)].mob : 'bandit';
    for (let i = 0; i < 2; i++){
      const m = spawnMob(mobType, { x:player.x, y:player.y, r:130, count:2 }, null);
      m.packAlert = 9999; m.provoked = true;
    }
    text = '⚠ MAI PHỤC!'; sub = 'Có kẻ phục kích giữa đường!'; color = '#ff5a4a';
    AudioSys.sfx('hurt', 0.7);
  } else if (r < 0.74){ // Năng lượng hội tụ
    player.silver += 60; player.khi += 20;
    text = 'KHÁM PHÁ · Năng Lượng Hội Tụ'; sub = 'Hít thở nguồn năng lượng quanh mình — +60◈ Lumen · +20 Bản Năng!'; color = '#7fd8e0';
  } else if (r < 0.90){ // Cao Thủ Ẩn Danh chỉ điểm vài chiêu
    const tv = 40 + Math.floor(player.level/12)*25;
    player.silver += tv*2;
    sub = `Một tay kiếm ẩn danh chỉ điểm vài đường — +${tv*2}◈ Lumen!`;
    text = 'KHÁM PHÁ · Cao Thủ Ẩn Danh'; color = '#d8baff';
  } else { // Giác ngộ bất chợt — trước đây giảm 30% tiêu hao Ascension Trial (cơ chế đột phá thủ
    // công đã tự động hoá từ đợt MU-hoá, giảm giá đó không còn ai tiêu thụ được nữa) — đổi thành
    // thưởng Anima thẳng cho tương xứng với các nhánh Khám Phá khác, giữ nguyên cảm giác "chợt tỉnh ngộ".
    const tv2 = 80 + Math.floor(player.level/12)*30;
    player.silver += tv2*2;
    text = 'KHÁM PHÁ · Giác Ngộ Bất Chợt'; color = '#9fd0ff';
    sub = `Chợt lóe lên một tia sáng trí tuệ — +${tv2*2}◈ Lumen!`;
  }
  zoneBanner = { text, sub, color, t:3.2 };
  AudioSys.sfx('quest', 0.7);
  addEffect({ type:'ring', x:player.x, y:player.y, r:70, color, big:true });
  calcDerived(); saveGame();
}
TITLES.push({ id:'tctk', name:'Kẻ Báo Thù', cond:p=>(p.revengeKills||0) >= 3, stats:{ atkPct:0.03 }, vfx:null });

// ============================================================
// Cloud Save Sync — giao tiếp với shell React qua postMessage
// ============================================================
(function(){
  if (!window.parent || window.parent === window) return; // chạy độc lập → bỏ qua
  function localSavedAt(){
    try {
      const raw = localStorage.getItem('vlcm_save');
      if (!raw) return 0;
      return JSON.parse(raw).savedAt || 0;
    } catch { return 0; }
  }
  window.addEventListener('message', function(ev){
    if (ev.origin !== window.location.origin) return;
    const msg = ev.data;
    if (!msg || msg.type !== 'vlcm:cloud-load' || !msg.data) return;
    try {
      const cloud = JSON.parse(msg.data);
      // Save cloud cũng phải qua cửa phiên bản. Trước đây nó được ghi thẳng vào localStorage,
      // nên một bản cloud đời cũ vẫn chui vào được và bật nút "Tiếp Tục" lên — bấm vào thì
      // loadGame() mới phát hiện quá cũ và xoá. Chặn ngay từ đây thay vì để người chơi bấm hụt.
      if ((cloud.v || 1) < SAVE_COMPAT) return;
      const cloudAt = cloud.savedAt || 0;
      if (cloudAt <= localSavedAt()) return; // bản local mới hơn hoặc bằng — giữ nguyên
      localStorage.setItem('vlcm_save', msg.data);
      if (!player){
        // đang ở màn menu → dựng lại danh sách ô ngay, không cần tải lại
        el('intro-story').classList.add('hidden');
        showMainMenu();
      } else {
        addFloat(player.x, player.y-70, '☁ Có save cloud mới hơn — tải lại trang để dùng bản đó', '#7ec8ff', 14);
      }
    } catch { /* best-effort — bỏ qua nếu lỗi */ }
  });
  // Báo cho shell biết game đã sẵn sàng nhận save cloud
  try { window.parent.postMessage({ type: 'vlcm:ready' }, window.location.origin); } catch { /* best-effort — bỏ qua nếu lỗi */ }
})();


